window.LIB_LAZY=window.LIB_LAZY||{};
window.LIB_LAZY["eusebiu-istoria#110"]=[{"v":1,"t":"Soter, episcopul bisericii din Roma, a murit după un episcopat de opt ani și i-a urmat Eleuter, al doisprezecelea de la apostoli. În al șaptesprezecelea an al împăratului Antonin Verus, prigoana poporului nostru a fost reaprinsă mai înverșunat în anumite ținuturi din pricina unei răscoale a mulțimilor din cetăți; și judecând după numărul dintr-un singur neam, zeci de mii au suferit martiriul în toată lumea. O însemnare a acestora a fost scrisă pentru urmași și, în adevăr, este vrednică de pomenire veșnică."},{"v":2,"t":"O povestire deplină, cuprinzând înștiințarea cea mai vrednică de încredere despre acest subiect, este dată în Culegerea noastră de Martiriuri, care alcătuiește o povestire atât instructivă, cât și istorică. Voi repeta aici acele părți ale acestei povestiri care pot fi necesare pentru scopul de față."},{"v":3,"t":"Alți scriitori de istorie însemnează biruințele războiului și trofeele câștigate de la dușmani, iscusința generalilor și vitejia bărbătească a ostașilor, mânjiți cu sânge și cu nenumărate măceluri de dragul copiilor și al țării și al altor averi."},{"v":4,"t":"Dar povestirea noastră a cârmuirii lui Dumnezeu va însemna în litere neșterse cele mai pașnice războaie purtate în folosul păcii sufletului și va povesti despre oameni care făceau fapte vitejești pentru adevăr mai degrabă decât pentru țară și pentru evlavie mai degrabă decât pentru cei mai dragi prieteni. Va transmite spre pomenire nepieritoare disciplina și tăria mult încercată a atleților religiei, trofeele câștigate de la demoni, biruințele asupra dușmanilor nevăzuți și cununile puse pe capetele lor."}];
window.LIB_LAZY["eusebiu-istoria#111"]=[{"v":1,"t":"Țara în care li s-a pregătit arena a fost Galia, ale cărei principale și mai vestite cetăți sunt Lyon și Vienne. Ronul trece prin amândouă, curgând într-un șuvoi larg prin toată regiunea."},{"v":2,"t":"Cele mai vestite biserici din acea țară au trimis o povestire despre martori bisericilor din Asia și Frigia, povestind în chipul următor ce s-a făcut printre ei. Voi da propriile lor cuvinte."},{"v":3,"t":"„Slujitorii lui Hristos care locuiesc la Vienne și Lyon, în Galia, către frații din toată Asia și Frigia, care țin aceeași credință și nădejde de răscumpărare, pace și har și slavă de la Dumnezeu Tatăl și Hristos Isus, Domnul nostru.”"},{"v":4,"t":"Apoi, după ce povestesc unele alte lucruri, își încep povestirea în acest chip: Mărimea necazului din această regiune și furia păgânilor împotriva sfinților și suferințele fericiților martori nu le putem povesti cu exactitate și nici nu ar putea fi, de fapt, însemnate."},{"v":5,"t":"Căci cu toată puterea lui potrivnicul s-a aruncat asupra noastră, dându-ne un gust mai dinainte al activității lui nestăpânite la venirea lui viitoare. S-a silit în orice chip să-și deprindă și să-și exercite slujitorii împotriva slujitorilor lui Dumnezeu, nu numai oprindu-ne de la case și băi și piețe, ci interzicând oricăruia dintre noi să fie văzut în orice loc."},{"v":6,"t":"Dar harul lui Dumnezeu a condus lupta împotriva lui și i-a izbăvit pe cei slabi și i-a pus ca stâlpi tari, în stare, prin răbdare, să îndure toată mânia Celui Rău. Și s-au luptat cu el, îndurând tot felul de rușine și vătămare; și socotind mari suferințele lor ca pe un lucru mic, s-au grăbit către Hristos, arătând cu adevărat că «suferințele vremii de acum nu sunt vrednice să fie puse alături de slava care ni se va descoperi după aceea». (Romani 8:18)"},{"v":7,"t":"Mai întâi de toate, au îndurat cu nobilețe nedreptățile îngrămădite asupra lor de popor; strigăte și lovituri și târâri și jafuri și uciderea cu pietre și închideri în temniță și toate lucrurile pe care o gloată înfuriată se desfată să le aplice dușmanilor și potrivnicilor."},{"v":8,"t":"Apoi, fiind duși în forum de hiliarh și de autoritățile cetății, au fost cercetați în prezența întregii mulțimi și, după ce au mărturisit, au fost închiși în temniță până la sosirea guvernatorului."},{"v":9,"t":"Când, după aceea, au fost aduși înaintea lui și el s-a purtat cu noi cu cea mai mare cruzime, Vettius Epagatus, unul dintre frați și un om plin de dragoste pentru Dumnezeu și pentru aproapele său, s-a amestecat. Viața lui era atât de consecventă încât, deși tânăr, căpătase o faimă egală cu a bătrânului Zaharia: căci «umbla în toate poruncile și rânduielile Domnului fără prihană» (Luca 1:6) și era neobosit în orice lucrare bună pentru aproapele său, râvnitor pentru Dumnezeu și înfocat în duh. Fiind astfel caracterul lui, nu a putut îndura judecata nerezonabilă împotriva noastră, ci a fost plin de indignare și a cerut să i se îngăduie să mărturisească în folosul fraților lui că între noi nu este nimic fără Dumnezeu sau nelegiuit."},{"v":10,"t":"Dar cei din jurul scaunului de judecată au strigat împotriva lui, căci era un om de seamă; iar guvernatorul a refuzat să-i împlinească cererea dreaptă și l-a întrebat doar dacă este și el creștin. Și el, mărturisind aceasta cu glas tare, a fost el însuși luat în rândul martorilor, numit Avocatul creștinilor, dar având Avocatul în el însuși, Duhul, mai din belșug decât Zaharia. A arătat aceasta prin plinătatea dragostei lui, fiind bine mulțumit chiar să-și dea viața în apărarea fraților. Căci era și este un adevărat ucenic al lui Hristos, «urmând Mielului oriunde merge». (Apocalipsa 14:4)"},{"v":11,"t":"Apoi ceilalți au fost împărțiți și protomartorii au fost vădit gata și și-au sfârșit mărturisirea cu toată râvna. Dar unii s-au arătat nepregătiți și neexersați, slabi încă și neputincioși să îndure o luptă atât de mare. Vreo zece dintre aceștia s-au dovedit avortoni, pricinuindu-ne mare durere și mâhnire peste măsură și slăbind râvna celorlalți care nu fuseseră încă prinși, dar care, deși suferind tot felul de necazuri, au rămas necontenit cu martorii și nu i-au părăsit."},{"v":12,"t":"Atunci toți ne-am temut mult din pricina nesiguranței în privința mărturisirii lor; nu pentru că ne temeam de suferințele de îndurat, ci pentru că ne uitam la sfârșit și ne era frică ca unii dintre ei să nu cadă."},{"v":13,"t":"Dar cei care erau vrednici erau prinși zi de zi, completându-le numărul, așa încât toate persoanele râvnitoare și cei prin care fuseseră în chip deosebit întemeiate treburile noastre au fost adunați laolaltă din cele două biserici."},{"v":14,"t":"Și au fost prinși și unii dintre slujitorii noștri păgâni, de vreme ce guvernatorul poruncise ca toți să fim cercetați public. Aceștia, fiind prinși în cursa lui Satan și temându-se pentru ei înșiși de chinurile pe care le vedeau îndurate de sfinți și fiind îndemnați și de ostași, ne-au învinuit pe nedrept de ospețe tiestiene și de împreunări edipiene și de fapte despre care nu numai că nu ne este îngăduit să vorbim sau să gândim, ci nici nu putem crede că au fost vreodată făcute de oameni."},{"v":15,"t":"Când aceste învinuiri au fost raportate, tot poporul s-a înfuriat ca fiarele sălbatice împotriva noastră, așa încât chiar și cei care fuseseră mai înainte cumpătați din pricina prieteniei erau acum nemăsurat de furioși și scrâșneau din dinți împotriva noastră. Și s-a împlinit ce spusese Domnul nostru: «Vine vremea când oricine vă va omorî va socoti că aduce slujbă lui Dumnezeu.» (Ioan 16:2)"},{"v":16,"t":"Apoi, în sfârșit, sfinții martori au îndurat suferințe de nedescris, Satan silindu-se cu înfocare ca și de la ei să iasă unele dintre clevetiri."},{"v":17,"t":"Dar toată mânia poporului și a guvernatorului și a ostașilor s-a ridicat nemăsurat împotriva lui Sanct, diaconul din Vienne, și a lui Maturus, un nou convertit, dar un nobil luptător, și împotriva lui Atal, nativ din Pergam, unde fusese totdeauna un stâlp și o temelie, și a Blandinei, prin care Hristos a arătat că lucrurile care par josnice și neînsemnate și disprețuite oamenilor sunt la Dumnezeu de mare slavă (1 Corinteni 1:27-28), prin dragostea față de El arătată în putere și nu lăudându-se cu înfățișarea."},{"v":18,"t":"Căci pe când noi toți tremuram și stăpâna ei pământească, care era și ea una dintre martore, se temea că din pricina slăbiciunii trupului ei nu va putea face mărturisire îndrăzneață, Blandina a fost plină de o asemenea putere încât a fost izbăvită și ridicată deasupra celor care o chinuiau pe rând din zori până seara în orice chip, așa încât au recunoscut că sunt biruiți și nu mai puteau să-i facă nimic. Și s-au uimit de răbdarea ei, pe când tot trupul ei era sfâșiat și zdrobit; și au mărturisit că unul dintre aceste feluri de chin era de ajuns ca să nimicească viața, ca să nu mai vorbim de atâtea și atât de mari suferințe."},{"v":19,"t":"Dar fericita femeie, ca un nobil atlet, își înnoia puterea în mărturisirea ei; și mângâierea și odihna și ușurarea ei din durerea suferințelor ei era în a striga: «Sunt creștină și nu se face nimic josnic de către noi.»"},{"v":20,"t":"Dar și Sanct a îndurat minunat și mai presus de om toate batjocurile pe care le-a suferit. În timp ce oamenii răi nădăjduiau, prin prelungirea și asprimea chinurilor lui, să scoată de la el ceva ce nu trebuia să spună, el s-a încins împotriva lor cu o asemenea tărie încât nu a vrut să-și spună nici măcar numele, nici neamul sau cetatea din care făcea parte, nici dacă este rob sau liber, ci a răspuns în limba romană la toate întrebările lor: «Sunt creștin.» Mărturisea aceasta în loc de nume și cetate și neam și orice altceva și poporul nu a auzit de la el niciun alt cuvânt."},{"v":21,"t":"S-a ridicat, deci, din partea guvernatorului și a chinuitorilor lui o mare dorință să-l biruiască; dar neavând nimic mai mult ce să-i facă, au prins în cele din urmă plăci de aramă înroșite în foc pe cele mai gingașe părți ale trupului lui."},{"v":22,"t":"Și acestea au ars, într-adevăr, dar el a rămas neplecat și neînduplecat, ferm în mărturisirea lui și împrospătat și întărit de izvorul ceresc al apei vieții, curgând din măruntaiele lui Hristos."},{"v":23,"t":"Și trupul lui era martor al suferințelor lui, fiind o singură rană și vânătaie, scos din formă și cu totul neasemănător cu un chip omenesc. Hristos, suferind în el, și-a arătat slava, izbăvindu-l de potrivnicul lui și făcându-l pildă pentru ceilalți, arătând că nimic nu este înfricoșător unde este dragostea Tatălui și nimic dureros unde este slava lui Hristos."},{"v":24,"t":"Căci când oamenii răi l-au chinuit a doua oară după câteva zile, socotind că, cu trupul lui umflat și inflamat într-atât încât nu putea suferi atingerea unei mâini, dacă vor aplica din nou aceleași unelte, îl vor birui sau cel puțin, prin moartea lui sub suferințele sale, ceilalți se vor înspăimânta, nu numai că nu s-a întâmplat aceasta, ci, împotriva oricărei așteptări omenești, trupul lui s-a ridicat și a stat drept în mijlocul chinurilor următoare și și-a reluat înfățișarea inițială și folosirea mădularelor, așa încât, prin harul lui Hristos, aceste a doua suferințe au devenit pentru el nu chin, ci vindecare."},{"v":25,"t":"Dar diavolul, socotind că o mistuise deja pe Biblis, care era una dintre cei care tăgăduiseră pe Hristos, dorind să-i sporească osânda prin rostirea de hulă, a adus-o iarăși la chin, ca s-o silească, fiind deja slăbită și neputincioasă, să dea relatări nelegiuite despre noi."},{"v":26,"t":"Dar ea și-a revenit sub suferință și, ca și cum s-ar fi trezit dintr-un somn adânc și fiind adusă aminte de chinul de acum de pedeapsa veșnică din iad, i-a contrazis pe hulitori. «Cum», a zis ea, «ar putea mânca copii cei care nu socotesc îngăduit să guste nici măcar sângele animalelor neraționale?» Și din acel moment s-a mărturisit creștină și i s-a dat loc în rândul martorilor."},{"v":27,"t":"Dar pe măsură ce chinurile tiranice au fost făcute de Hristos fără efect prin răbdarea celor fericiți, diavolul a născocit alte meșteșuguri — închiderea în cele mai întunecate și mai scârboase părți ale temniței, întinderea picioarelor până la a cincea gaură în butuci și celelalte batjocuri pe care slujitorii lui obișnuiesc să le aplice prizonierilor când sunt furioși și plini de diavol. Foarte mulți au fost înăbușiți în temniță, fiind aleși de Domnul pentru acest fel de moarte, ca să arate în ei slava Lui."},{"v":28,"t":"Căci unii, deși fuseseră chinuiți atât de crud încât părea cu neputință să mai trăiască, chiar cu cea mai atentă îngrijire, totuși, lipsiți de atenție omenească, au rămas în temniță, fiind întăriți de Domnul și înviorați și în trup, și în suflet; și îi îndemnau și îi îmbărbătau pe ceilalți. Dar cei care erau tineri și arestați de curând, așa încât trupurile lor nu se obișnuiseră cu chinul, nu au putut îndura asprimea închiderii și au murit în temniță."},{"v":29,"t":"Fericitul Potin, căruia i se încredințase episcopatul Lyonului, a fost târât la scaunul de judecată. Avea peste nouăzeci de ani și era foarte slab, abia în stare să respire din pricina slăbiciunii trupești; dar a fost întărit de râvna duhovnicească prin dorința lui înfocată de martiriu. Deși trupul lui era uzat de bătrânețe și boală, viața lui a fost păstrată ca Hristos să triumfe în ea."},{"v":30,"t":"Când a fost adus de ostași la tribunal, însoțit de magistrații civili și de o mulțime care striga împotriva lui în fel și chip ca și cum ar fi fost Hristos însuși, a dat o nobilă mărturie."},{"v":31,"t":"Fiind întrebat de guvernator cine este Dumnezeul creștinilor, a răspuns: «Dacă ești vrednic, vei cunoaște.» Atunci a fost târât cu asprime și a primit lovituri de tot felul. Cei aproape de el îl loveau cu mâinile și cu picioarele, fără a ține seama de vârsta lui; și cei de departe aruncau în el tot ce puteau apuca; toți socotind că ar fi vinovați de mare răutate și nelegiuire dacă ar omite vreo batjocură cu putință. Căci astfel socoteau că răzbună pe propriii lor zei. Abia în stare să respire, a fost aruncat în temniță și a murit după două zile."},{"v":32,"t":"Atunci s-a petrecut o anume mare rânduială a lui Dumnezeu și îndurarea lui Isus s-a arătat peste măsură, într-un chip rar văzut între frăție, dar nu peste puterea lui Hristos."},{"v":33,"t":"Căci cei care se lepădaseră la prima arestare au fost închiși cu ceilalți și au îndurat cumplite suferințe, așa încât lepădarea lor nu le-a folosit la nimic nici măcar pentru moment. Dar cei care au mărturisit ce erau au fost închiși ca creștini, nicio altă învinuire nefiind adusă împotriva lor. Dar cei dintâi au fost tratați după aceea ca ucigași și spurcați și au fost pedepsiți de două ori mai aspru decât ceilalți."},{"v":34,"t":"Căci bucuria martiriului și nădejdea făgăduințelor și dragostea pentru Hristos și Duhul Tatălui îi sprijineau pe cei din urmă; dar conștiința îi chinuia atât de mult pe cei dintâi încât se deosebeau ușor de toți ceilalți chiar după înfățișarea lor când erau scoși afară."},{"v":35,"t":"Căci cei dintâi ieșeau bucurându-se, slava și harul fiind amestecate în chipurile lor, așa încât chiar și lanțurile lor păreau frumoase podoabe, ca ale unei mirese împodobite cu franjuri de aur felurite; și erau parfumați cu bunul miros al lui Hristos, așa încât unii socoteau că fuseseră unși cu unsoare pământească. Dar ceilalți erau abătuți și smeriți și descurajați și plini de orice fel de rușine și erau batjocoriți de păgâni ca nenobili și slabi, purtând învinuirea de ucigași și pierzând unicul Nume cinstit și slăvit și dătător de viață. Restul, văzând aceasta, au fost întăriți și, când au fost prinși, au mărturisit fără șovăire, neluând în seamă înduplecările diavolului."},{"v":36,"t":"După alte câteva cuvinte continuă: După aceste lucruri, în sfârșit, martiriurile lor au fost împărțite în toate formele. Căci împletind o cunună de felurite culori și de tot felul de flori, au înfățișat-o Tatălui. Se cuvenea, deci, ca nobilii atleți, după ce îndurând o luptă din multe feluri și biruind cu slavă, să primească cununa mare și nestricăcioasă."},{"v":37,"t":"Maturus, deci, și Sanct și Blandina și Atal au fost duși la amfiteatru ca să fie expuși fiarelor sălbatice și ca să dea publicului păgân un spectacol de cruzime, o zi pentru lupta cu fiarele sălbatice fiind rânduită anume din pricina poporului nostru."},{"v":38,"t":"Și Maturus, și Sanct au trecut din nou prin tot chinul în amfiteatru, ca și cum nu ar fi suferit nimic înainte, sau mai bine zis ca și cum, după ce biruiseră deja pe potrivnicul lor în multe întreceri, se luptau acum pentru cununa însăși. Au îndurat din nou obișnuita trecere printre doi rânduri de lovitori și violența fiarelor sălbatice și tot ce cerea sau dorea poporul înfuriat și, în cele din urmă, scaunul de fier pe care trupurile lor, fiind fripte, îi chinuiau cu fumul."},{"v":39,"t":"Și nu s-au oprit prigonitorii cu aceasta, ci erau și mai înnebuniți împotriva lor, hotărâți să le biruie răbdarea. Dar nici așa nu au auzit de la Sanct niciun cuvânt, afară de mărturisirea pe care o rostise de la început."},{"v":40,"t":"Aceștia, deci, după ce viața lor continuase multă vreme prin marea luptă, au fost jertfiți în cele din urmă, fiind făcuți în acea zi un spectacol pentru lume, în locul obișnuitei varietăți de lupte."},{"v":41,"t":"Dar Blandina a fost atârnată de un stâlp și expusă să fie devorată de fiarele sălbatice care aveau s-o atace. Și pentru că părea ca și cum ar atârna pe o cruce și din pricina rugăciunilor ei înfocate, a insuflat luptătorilor mare râvnă. Căci se uitau la ea în lupta ei și vedeau cu ochii lor din afară, în chipul surorii lor, pe Cel care a fost răstignit pentru ei, ca să-i convingă pe cei care cred în El că oricine pătimește pentru slava lui Hristos are totdeauna părtășie cu Dumnezeul cel viu."},{"v":42,"t":"Deoarece niciuna dintre fiarele sălbatice nu s-a atins de ea în acel timp, a fost coborâtă de pe stâlp și aruncată din nou în temniță. A fost păstrată astfel pentru o altă luptă, ca, biruitoare în mai multe întreceri, să facă pedeapsa șarpelui celui strâmb de neînlăturat; și, deși mică și slabă și disprețuită, dar îmbrăcată cu Hristos, puternicul și biruitorul Atlet, să stârnească râvna fraților și, după ce a biruit de multe ori pe potrivnic, să primească, prin lupta ei, cununa nestricăcioasă."},{"v":43,"t":"Dar pe Atal îl cerea poporul cu glas tare, pentru că era o persoană de seamă. A intrat în luptă cu bunăvoință din pricina unei conștiințe bune și a adevăratei lui deprinderi în disciplina creștină și pentru că fusese totdeauna un martor al adevărului între noi."},{"v":44,"t":"A fost purtat în jurul amfiteatrului, o tăbliță fiind purtată înaintea lui pe care era scris în limba romană: «Acesta este Atal creștinul», și poporul era plin de indignare împotriva lui. Dar când guvernatorul a aflat că este roman, a poruncit să fie dus înapoi cu restul celor care erau în temniță despre care scrisese lui Cezar și al căror răspuns îl aștepta."},{"v":45,"t":"Dar timpul de mijloc nu a fost risipit nici fără rod pentru ei; căci prin răbdarea lor s-a arătat îndurarea nemăsurată a lui Hristos. Căci prin viața lor continuată, morții au fost făcuți vii și martorii au arătat favoare celor care nu izbutiseră să mărturisească. Și mama fecioară s-a bucurat mult primind vii pe cei pe care îi născuse ca morți."},{"v":46,"t":"Căci prin înrâurirea lor mulți dintre cei care se lepădaseră au fost restabiliți și renăscuți și reaprinși de viață și au învățat să mărturisească. Și fiind făcuți vii și întăriți, au mers la scaunul de judecată să fie din nou interogați de guvernator; Dumnezeu, care nu dorește moartea păcătosului (Ezechiel 33:11), ci îl cheamă cu milă la pocăință, tratându-i cu bunătate."},{"v":47,"t":"Căci Cezar poruncise ca ei să fie dați la moarte, dar cei care s-ar lepăda să fie liberați. De aceea, la începutul sărbătorii publice care avea loc acolo și la care participau mulțimi de oameni din toate neamurile, guvernatorul a adus pe cei fericiți la scaunul de judecată, ca să facă din ei un spectacol și o priveliște pentru mulțime. De aceea i-a și cercetat din nou și i-a decapitat pe cei care păreau să aibă cetățenie romană, dar pe ceilalți i-a trimis la fiare sălbatice."},{"v":48,"t":"Și Hristos a fost slăvit mult în cei care Îl tăgăduiseră mai înainte, căci, împotriva așteptării păgânilor, au mărturisit. Căci au fost cercetați deosebit, ca unii care aveau să fie liberați; dar mărturisind, au fost adăugați la rândul martorilor. Dar unii au rămas în afară, care nu avuseseră niciodată nicio urmă de credință, nici vreo închipuire a hainei de nuntă (Matei 22:11), nici o înțelegere a fricii de Dumnezeu; ci, ca fii ai pierzării, au hulit Calea prin apostazia lor."},{"v":49,"t":"Dar toți ceilalți au fost adăugați la Biserică. Pe când aceștia erau cercetați, un anume Alexandru, frigian de neam și doctor de meserie, care locuise în Galia mulți ani și era bine cunoscut tuturor din pricina dragostei lui pentru Dumnezeu și a îndrăznelii vorbirii lui (căci nu era fără parte de harul apostolic), stând înaintea scaunului de judecată și îmbărbătându-i prin semne să mărturisească, li s-a arătat celor de față ca și cum ar fi fost în durerile nașterii."},{"v":50,"t":"Dar poporul, înfuriat pentru că cei care se lepădaseră mai înainte mărturiseau acum, a strigat împotriva lui Alexandru ca și cum ar fi fost pricina acestui lucru. Atunci guvernatorul l-a chemat și l-a întrebat cine este. Și când a răspuns că este creștin, fiind foarte mânios, l-a osândit la fiare sălbatice. Și a doua zi a intrat împreună cu Atal. Căci, ca să facă pe plac poporului, guvernatorul poruncise din nou ca Atal să fie dat fiarelor sălbatice."},{"v":51,"t":"Și au fost chinuiți în amfiteatru cu toate uneltele născocite pentru acest scop și, după ce au îndurat o foarte mare luptă, au fost jertfiți în cele din urmă. Alexandru nu a gemut și nu a murmurat în niciun chip, ci a vorbit în inima lui cu Dumnezeu."},{"v":52,"t":"Dar când Atal a fost așezat pe scaunul de fier și fumul s-a ridicat din trupul lui arzând, a spus poporului în limba romană: «Iată! Ceea ce faceți voi este a devora oameni; dar noi nu devorăm oameni și nici nu facem vreun alt lucru rău.» Și fiind întrebat ce nume are Dumnezeu, a răspuns: «Dumnezeu nu are un nume cum are omul.»"},{"v":53,"t":"După toate acestea, în ultima zi a întrecerilor, Blandina a fost adusă din nou, cu Pontic, un băiat de vreo cincisprezece ani. Fuseseră aduși în fiecare zi ca să fie martori la suferințele celorlalți și fuseseră îndemnați să jure pe idoli. Dar pentru că au rămas statornici și i-au disprețuit, mulțimea s-a înfuriat, așa încât nu a avut milă de tinerețea băiatului și nici respect pentru sexul femeii."},{"v":54,"t":"De aceea i-au expus la toate cumplitele suferințe și i-au dus prin tot cercul chinurilor, îndemnându-i necontenit să jure, dar neputând să izbutească aceasta; căci Pontic, îmbărbătat de sora lui, așa încât și păgânii puteau vedea că îl întărește și îl încurajează, după ce a îndurat cu nobilețe orice chin, și-a dat duhul."},{"v":55,"t":"Dar fericita Blandina, cea din urmă dintre toți, după ce, ca o mamă nobilă, își îmbărbătase copiii și îi trimisese înaintea ei biruitori la Rege, a îndurat ea însăși toate luptele lor și s-a grăbit după ei, veselă și bucurându-se de plecarea ei ca și cum ar fi fost chemată la un ospăț de nuntă, și nu aruncată la fiare sălbatice."},{"v":56,"t":"Și, după biciuire, după fiarele sălbatice, după scaunul pentru fript, a fost în cele din urmă închisă într-o plasă și aruncată înaintea unui taur. Și, după ce a fost aruncată încoace și încolo de animal, dar neavând nicio simțire a lucrurilor care i se întâmplau, din pricina nădejdii ei și a ținerii ei tari de ceea ce i se încredințase și a părtășiei ei cu Hristos, a fost jertfită și ea. Și păgânii înșiși au mărturisit că niciodată între ei nu a îndurat o femeie atâtea și atât de cumplite chinuri."},{"v":57,"t":"Dar nici așa nu s-a săturat nebunia și cruzimea lor față de sfinți. Căci, stârniți de Fiara Sălbatică, neamurile sălbatice și barbare nu se potoleau ușor, și violența lor a găsit un alt prilej deosebit în trupurile moarte."},{"v":58,"t":"Căci, din lipsa rațiunii bărbătești, faptul că fuseseră biruiți nu le-a făcut rușine, ci a aprins mai mult mânia lor ca a unei fiare sălbatice și a stârnit deopotrivă ura guvernatorului și a poporului de a ne trata cu nedreptate; ca să se împlinească Scriptura: «Cel fără lege să fie și mai departe fără lege și cel drept să fie și mai departe drept.»"},{"v":59,"t":"Căci au aruncat câinilor pe cei care muriseră înăbușiți în temniță, păzindu-i cu grijă noaptea și ziua, ca nu cumva să fie îngropat vreunul de noi. Și au expus rămășițele lăsate de fiarele sălbatice și de foc, sfâșiate și carbonizate, și au pus capetele celorlalți lângă trupurile lor și le-au păzit în același chip de îngropare printr-o strajă de ostași multe zile."},{"v":60,"t":"Și unii se înfuriau și scrâșneau din dinți împotriva lor, dorind să aplice asupra lor o răzbunare mai aspră; dar alții râdeau și își băteau joc de ei, mărind pe propriii lor idoli și punând în seama lor pedeapsa creștinilor. Chiar și cei mai cu minte și cei care păruseră că simpatizează oarecum îi mustrau adesea, zicând: «Unde este Dumnezeul lor și ce le-a folosit religia lor, pe care au ales-o mai degrabă decât viața?»"},{"v":61,"t":"Astfel era de felurită purtarea lor față de noi; dar noi eram într-o adâncă mâhnire pentru că nu puteam îngropa trupurile. Căci nici noaptea nu ne-a folosit pentru aceasta, nici banii nu au înduplecat, nici rugămintea nu a mișcat la milă; ci vegheau în orice chip, ca și cum împiedicarea îngropării le-ar fi adus vreun mare avantaj. Pe lângă aceasta, spun după alte lucruri:"},{"v":62,"t":"Trupurile martirilor, fiind astfel în orice chip arătate și expuse șase zile, au fost arse după aceea și reduse la cenușă și măturate în Ron de oamenii răi, așa încât nicio urmă a lor să nu se arate pe pământ."},{"v":63,"t":"Și aceasta au făcut-o, ca și cum ar fi fost în stare să-L biruie pe Dumnezeu și să le împiedice renașterea; «ca», după cum spuneau, «să nu aibă nădejde de înviere, în a cărei încredere ne aduc această religie străină și nouă și disprețuiesc lucrurile cumplite și sunt gata chiar să meargă la moarte cu bucurie. Acum să vedem dacă vor învia și dacă Dumnezeul lor este în stare să-i ajute și să-i izbăvească din mâinile noastre.»"}];
window.LIB_LAZY["eusebiu-istoria#112"]=[{"v":1,"t":"Asemenea lucruri s-au întâmplat bisericilor lui Hristos sub pomenitul împărat, din care putem presupune cu temei întâmplările din celelalte provincii. Este cuvenit să adăugăm alte alegeri din aceeași scrisoare, în care cumpătarea și mila acestor martori sunt însemnate în cuvintele următoare:"},{"v":2,"t":"Erau și atât de râvnitori în imitarea lui Hristos — «care, fiind în chipul lui Dumnezeu, nu a socotit ca pradă a fi deopotrivă cu Dumnezeu» (Filipeni 2:6) — încât, deși ajunseseră la o asemenea cinste și dăduseră mărturie nu o dată sau de două ori, ci de multe ori — fiind aduși înapoi în temniță de la fiarele sălbatice, acoperiți de arsuri și cicatrice și răni — totuși nu se proclamau martori și nu ne îngăduiau să ne adresăm lor cu acest nume. Dacă vreunul dintre noi, în scrisoare sau în convorbire, vorbea de ei ca de martori, îl mustrau aspru."},{"v":3,"t":"Căci cedau cu bucurie numele de Martor lui Hristos, «Martorul credincios și adevărat» (Apocalipsa 3:14) și «întâi-născut din morți» (Apocalipsa 1:5) și domnitor al vieții lui Dumnezeu; și ne aduceau aminte de martorii care plecaseră deja și ziceau: «Aceia sunt deja martori pe care Hristos i-a socotit vrednici să fie luați în mărturisirea lor, pecetluindu-și mărturia prin plecarea lor; dar noi suntem smeriți și umili mărturisitori.» Și rugau pe frați cu lacrimi să se aducă rugăciuni înfocate ca ei să fie făcuți desăvârșiți."},{"v":4,"t":"Ei arătau în faptele lor puterea «mărturiei», arătând mare îndrăzneală față de toți frații și își făceau vădită nobilețea prin răbdare și neînfricare și curaj, dar refuzau titlul de Martori ca unul care să-i deosebească de frații lor, fiind plini de frica de Dumnezeu."},{"v":5,"t":"Puțin mai departe spun: „S-au smerit sub mâna cea tare, prin care sunt acum mult înălțați. Au apărat pe toți, dar nu au învinuit pe nimeni. Au iertat pe toți, dar nu au legat pe nimeni. Și s-au rugat pentru cei care le făcuseră cruzimi, întocmai ca Ștefan, martorul desăvârșit, «Doamne, nu le socoti lor păcatul acesta». (Fapte 7:60) Dar dacă s-a rugat pentru cei care l-au ucis cu pietre, cu cât mai mult pentru frați!”"},{"v":6,"t":"Și iarăși, după ce pomenesc alte lucruri, spun: Căci, prin sinceritatea dragostei lor, cea mai mare luptă a lor cu el a fost ca Fiara, fiind înăbușită, să scoată vii pe cei pe care socotea că îi înghițise. Căci nu se lăudau față de cei căzuți, ci îi ajutau în nevoia lor cu acele lucruri în care ei înșiși aveau belșug, având mila unei mame și vărsând multe lacrimi pentru ei înaintea Tatălui."},{"v":7,"t":"Au cerut viață și El le-a dat-o și ei au împărțit-o cu aproapele lor. Biruitori peste toate, au plecat la Dumnezeu. Iubind totdeauna pacea și recomandându-ne pacea, au mers în pace la Dumnezeu, nelăsând nicio durere mamei lor, nici dezbinare sau ceartă fraților, ci bucurie și pace și înțelegere și dragoste."},{"v":8,"t":"Această însemnare a dragostei acelor fericiți față de frații care căzuseră poate fi adăugată cu folos din pricina dispoziției neomenoase și fără milă a celor care, după aceste întâmplări, s-au purtat fără cruțare față de mădularele lui Hristos."}];
window.LIB_LAZY["eusebiu-istoria#113"]=[{"v":1,"t":"Aceeași scrisoare a pomeniților martori cuprinde o altă povestire vrednică de pomenire. Nimeni nu se va împotrivi ca să o aducem la cunoștința cititorilor noștri."},{"v":2,"t":"Sună astfel: Căci un anume Alcibiade, care era unul dintre ei, ducea o viață foarte aspră, neluând nimic deloc decât pâine și apă. Când s-a silit să continue același fel de viață în temniță, i s-a descoperit lui Atal după prima lui luptă în amfiteatru că Alcibiade nu face bine refuzând făpturile lui Dumnezeu și punând o piatră de poticnire înaintea altora."},{"v":3,"t":"Și Alcibiade a ascultat și a luat din toate fără oprire, mulțumind lui Dumnezeu. Căci nu erau lipsiți de harul lui Dumnezeu, ci Duhul Sfânt le era sfătuitor. Să ne ajungă acestea despre aceste lucruri."},{"v":4,"t":"Urmașii lui Montan, Alcibiade și Teodot în Frigia dădeau acum întâi larg circulație pretenției lor în privința proorociei — căci multele alte minuni care, prin darul lui Dumnezeu, se făceau încă în diferitele biserici făceau ca proorocirea lor să fie ușor crezută de mulți — și pe măsură ce s-a ridicat dezbinare în privința lor, frații din Galia și-au înfățișat propria lor judecată prudentă și foarte ortodoxă în această chestiune și au publicat și câteva epistole de la martorii care fuseseră dați la moarte printre ei. Pe acestea le-au trimis, când erau încă în temniță, fraților din Asia și Frigia și, de asemenea, lui Eleuter, care era atunci episcop al Romei, negociind pentru pacea bisericilor."}];
window.LIB_LAZY["eusebiu-istoria#114"]=[{"v":1,"t":"Aceiași martori l-au recomandat și pe Irineu, care era deja în acel timp prezbiter al parohiei Lyonului, pomenitului episcop al Romei, spunând multe lucruri bune despre el, după cum arată următorul extras:"},{"v":2,"t":"„Ne rugăm, părinte Eleuter, ca să te bucuri în Dumnezeu în toate și totdeauna. Am cerut fratelui și tovarășului nostru Irineu să-ți ducă această scrisoare și te rugăm să-l ții în cinste, ca râvnitor pentru legământul lui Hristos. Căci dacă am socoti că slujba poate da dreptate cuiva, l-am recomanda printre cei dintâi ca prezbiter al bisericii, ceea ce este poziția lui.”"},{"v":3,"t":"De ce să transcriem catalogul martorilor dat în scrisoarea deja pomenită, dintre care unii au fost decapitați, alții aruncați la fiare sălbatice, iar alții au adormit în temniță, sau să dăm numărul mărturisitorilor încă în viață în acel timp? Căci oricine dorește poate găsi ușor povestirea deplină consultând scrisoarea însăși, care, după cum am spus, este însemnată în Culegerea noastră de Martiriuri. Astfel au fost întâmplările care au avut loc sub Antonin."}];
window.LIB_LAZY["eusebiu-istoria#115"]=[{"v":1,"t":"Se povestește că Marcus Aurelius Cezar, fratele lui Antonin, fiind pe cale să dea bătălie germanilor și sarmaților, era în mare nevoie din pricina oastei sale care suferea de sete. Dar ostașii așa-numitei legiuni Melitene, prin credința care a dat putere din acel timp până în prezent, când au fost așezați în rânduială înaintea dușmanului, au îngenuncheat la pământ, după obiceiul nostru de rugăciune, și s-au dat la rugăciuni către Dumnezeu."},{"v":2,"t":"Aceasta a fost într-adevăr o priveliște ciudată pentru dușman, dar se povestește că a urmat îndată un lucru și mai ciudat. Fulgerul a pus pe dușman pe fugă și nimicire, dar o ploaie a împrospătat oastea celor care chemaseră pe Dumnezeu, care toți fuseseră pe punctul de a pieri de sete."},{"v":3,"t":"Această istorie este povestită de scriitori necreștini care au binevoit să trateze vremurile pomenite și a fost însemnată și de ai noștri. De acei istorici care erau străini de credință, minunea este pomenită, dar nu este recunoscută ca răspuns la rugăciunile noastre. Dar de ai noștri, ca prieteni ai adevărului, întâmplarea este povestită într-un chip simplu și fără meșteșug."},{"v":4,"t":"Printre aceștia este Apolinarie, care spune că din acel timp legiunea prin ale cărei rugăciuni s-a făcut minunea a primit de la împărat un titlu potrivit întâmplării, fiind numită în limba romanilor Legiunea Tunătoare."},{"v":5,"t":"Tertulian este un martor vrednic de încredere al acestor lucruri. În Apologia pentru credință, pe care a adresat-o Senatului roman și care lucrare am pomenit-o deja, el întărește istoria cu dovezi mai mari și mai tari."},{"v":6,"t":"Scrie că mai există încă scrisori ale preaînțeleptului împărat Marcu în care mărturisește că oastea lui, fiind pe punctul de a pieri de sete în Germania, a fost scăpată prin rugăciunile creștinilor. Și spune și că acest împărat a amenințat cu moartea pe cei care aduceau învinuire împotriva noastră."},{"v":7,"t":"Adaugă mai departe: „Ce fel de legi sunt acelea de care se slujesc împotriva noastră singuri oameni nelegiuiți, nedrepți și cruzi? Pe care Vespasian, deși biruise pe iudei, nu le-a luat în seamă; pe care Traian le-a anulat în parte, oprind căutarea creștinilor; pe care nici Adrian, deși iscoditor în toate chestiunile, nici cel numit Pios nu le-au încuviințat.” Dar să trateze oricine aceste lucruri cum vrea; noi trebuie să trecem la ce a urmat."},{"v":8,"t":"Potin murind cu ceilalți martiri din Galia la nouăzeci de ani, Irineu i-a urmat în episcopatul bisericii din Lyon. Am aflat că, în tinerețea lui, a fost ascultător al lui Policarp."},{"v":9,"t":"În cartea a treia a lucrării sale Împotriva ereziilor a inserat o listă a episcopilor Romei, coborând-o până la Eleuter (ale cărui vremuri le cercetăm acum), sub care și-a alcătuit lucrarea. Scrie astfel:"}];
window.LIB_LAZY["eusebiu-istoria#116"]=[{"v":1,"t":"Fericiții apostoli, după ce au întemeiat și așezat biserica, au încredințat slujba episcopatului lui Lin. Pavel vorbește despre acest Lin în Epistolele către Timotei. (2 Timotei 4:21)"},{"v":2,"t":"I-a urmat Anencletus și, după Anencletus, al treilea de la apostoli, Clement a primit episcopatul. Văzuse și vorbise cu fericiții apostoli și predica lor mai suna încă în urechile lui și tradiția lor era încă înaintea ochilor lui. Și nu era singur în aceasta, căci mulți care fuseseră învățați de apostoli mai trăiau încă."},{"v":3,"t":"În vremea lui Clement, ridicându-se o gravă dezbinare între frații din Corint, biserica Romei a trimis corintenilor o scrisoare foarte potrivită, împăcându-i în pace, reînnoindu-le credința și vestind învățătura primită de curând de la apostoli."},{"v":4,"t":"Puțin mai departe spune: Evarist i-a urmat lui Clement și Alexandru lui Evarist. Apoi a fost rânduit Xist, al șaselea de la apostoli. După el, Telesfor, care a suferit martiriul cu slavă; apoi Higin; apoi Pius; și după el Anicet; Soter i-a urmat lui Anicet; și acum, în al doisprezecelea loc de la apostoli, Eleuter ține slujba de episcop."},{"v":5,"t":"În aceeași rânduială și succesiune a coborât de la apostoli până la noi tradiția din Biserică și predica adevărului."}];
window.LIB_LAZY["eusebiu-istoria#117"]=[{"v":1,"t":"Aceste lucruri le însemnează Irineu, în acord cu povestirile deja date de noi, în lucrarea care cuprinde cinci cărți și căreia i-a dat titlul Combaterea și răsturnarea cunoștinței numite pe nedrept așa. În cartea a doua a aceluiași tratat arată că manifestări ale puterii dumnezeiești și minunate au continuat până în vremea lui în unele biserici."},{"v":2,"t":"El spune: „Dar atât de departe sunt de a învia morți, cum i-a înviat Domnul și apostolii prin rugăciune. Și adesea în frăție, când, din pricina vreunei nevoi, toată Biserica noastră a rugat cu post și multă rugăciune, duhul celui mort s-a întors și omul a fost redat prin rugăciunile sfinților.”"},{"v":3,"t":"Și iarăși, după alte observații, spune: Dacă vor spune că și Domnul a făcut aceste lucruri numai în aparență, îi vom trimite la scrierile proorocești și vom arăta din ele că toate lucrurile s-au spus mai dinainte despre El în acest chip și s-au împlinit întocmai; și că numai El este Fiul lui Dumnezeu. De aceea adevărații Lui ucenici, primind har de la El, săvârșesc asemenea lucrări în Numele Lui spre folosul altor oameni, după cum a primit fiecare darul de la El."},{"v":4,"t":"Căci unii dintre ei alungă demoni în chip eficient și adevărat, așa încât cei curățiți de duhuri rele cred adesea și se unesc cu Biserica. Alții au o prevedere a întâmplărilor viitoare și vedenii și descoperiri proorocești. Încă alții vindecă pe bolnavi prin punerea mâinilor și îi redau sănătății. Și, după cum am spus, chiar persoane moarte au fost înviate și au rămas cu noi mulți ani."},{"v":5,"t":"Dar de ce să spunem mai mult? Nu este cu putință să înșirăm numărul darurilor pe care Biserica, în toată lumea, le-a primit de la Dumnezeu în numele lui Isus Hristos, care a fost răstignit sub Pontiu Pilat, și le exercită zilnic spre folosul păgânilor, neamăgind pe nimeni și nefăcând-o pentru bani. Căci după cum a primit degeaba de la Dumnezeu, degeaba și slujește."},{"v":6,"t":"Și în alt loc același autor scrie: „Cum auzim și că mulți frați din Biserică au daruri proorocești și vorbesc, prin Duhul, în tot felul de limbi și scot la lumină lucrurile ascunse ale oamenilor spre binele lor și vestesc tainele lui Dumnezeu.” Atât în privința faptului că felurite daruri au rămas între cei vrednici chiar până în acel timp."}];
window.LIB_LAZY["eusebiu-istoria#118"]=[{"v":1,"t":"De vreme ce, la începutul acestei lucrări, am făgăduit să dăm, când va fi nevoie, cuvintele bătrânilor prezbiteri și scriitorilor din vechime ai Bisericii, în care au declarat acele tradiții care au coborât la ei cu privire la cărțile canonice, și de vreme ce Irineu a fost unul dintre ei, vom da acum cuvintele lui și, mai întâi, ce spune despre sfintele Evanghelii:"},{"v":2,"t":"Matei și-a publicat Evanghelia între evrei în limba lor, în timp ce Petru și Pavel predicau și întemeiau biserica în Roma."},{"v":3,"t":"După plecarea lor, Marcu, ucenicul și tălmaciul lui Petru, ne-a transmis și el în scris acele lucruri pe care Petru le predicase; și Luca, însoțitorul lui Pavel, a însemnat într-o carte Evanghelia pe care o vestise Pavel."},{"v":4,"t":"După aceea, Ioan, ucenicul Domnului, care s-a rezemat și pe pieptul Lui, și-a publicat Evanghelia, pe când stătea la Efes în Asia."},{"v":5,"t":"Aceste lucruri le spune în cartea a treia a pomenitei lui lucrări. În cartea a cincea vorbește astfel despre Apocalipsa lui Ioan și numărul numelui lui Antihrist: „Fiind așa lucrurile și acest număr găsindu-se în toate copiile încuviințate și vechi și cei care l-au văzut pe Ioan față în față confirmându-l și rațiunea învățându-ne că numărul numelui fiarei, după felul de socotire între greci, se arată în literele sale....”"},{"v":6,"t":"Și mai departe spune despre același: „Nu suntem destul de îndrăzneți să vorbim cu încredere despre numele lui Antihrist. Căci dacă ar fi fost necesar ca numele lui să fie declarat limpede în timpul de acum, ar fi fost vestit de cel care a văzut descoperirea. Căci a fost văzută nu de mult, ci aproape în generația noastră, spre sfârșitul domniei lui Domițian.”"},{"v":7,"t":"Aceste lucruri le spune despre Apocalipsă în lucrarea pomenită. Pomenește și Prima Epistolă a lui Ioan, luând multe dovezi din ea, și de asemenea Prima Epistolă a lui Petru. Și nu numai că cunoaște, ci și primește Păstorul, scriind astfel: „Bine a spus Scriptura, zicând: «Mai întâi de toate crede că Dumnezeu este unul, care a creat și a desăvârșit toate lucrurile»”, etc."},{"v":8,"t":"Și se slujește aproape de cuvintele exacte din Înțelepciunea lui Solomon, zicând: „Vederea lui Dumnezeu aduce nemurirea, dar nemurirea ne apropie de Dumnezeu.” Pomenește și memoriile unui anume prezbiter apostolic, al cărui nume îl trece sub tăcere, și dă tâlcuirile lui ale Sfintelor Scripturi."},{"v":9,"t":"Și se referă la Iustin Martirul și la Ignatie, folosind mărturii și din scrierile lor. Pe lângă aceasta, făgăduiește să-l combată pe Marcion din propriile lui scrieri, într-o lucrare deosebită."},{"v":10,"t":"Despre traducerea Scripturilor insuflate de cei Șaptezeci, auzi chiar cuvintele pe care le scrie: „Dumnezeu s-a făcut în adevăr om și Domnul însuși ne-a mântuit, dând semnul fecioarei; dar nu cum spun unii care cutează acum să traducă Scriptura: «Iată, o tânără va rămâne însărcinată și va naște un fiu», cum au tâlcuit Teodotion din Efes și Aquila din Pont, amândoi prozeliți iudei; urmându-i pe care, ebioniții spun că a fost născut de Iosif.”"},{"v":11,"t":"Puțin după aceea adaugă: Căci înainte ca romanii să-și fi întemeiat imperiul, pe când macedonenii țineau încă Asia, Ptolemeu, fiul lui Lagos, dorind să împodobească biblioteca pe care o întemeiase în Alexandria cu scrierile vrednice ale tuturor oamenilor, a cerut poporului din Ierusalim să-și traducă Scripturile în limba greacă."},{"v":12,"t":"Dar, fiind ei atunci supuși macedonenilor, au trimis lui Ptolemeu șaptezeci de bătrâni, care erau cei mai iscusiți dintre ei în Scripturi și în ambele limbi. Astfel a săvârșit Dumnezeu planul Său."},{"v":13,"t":"Dar voind să-i încerce pe fiecare deosebit, căci se temea ca nu cumva, sfătuindu-se laolaltă, să ascundă adevărul Scripturilor prin tâlcuirea lor, i-a despărțit unii de alții și a poruncit tuturor să scrie aceeași traducere. A făcut aceasta pentru toate cărțile."},{"v":14,"t":"Dar când s-au adunat în prezența lui Ptolemeu și și-au comparat traducerile deosebite, Dumnezeu a fost slăvit și Scripturile au fost recunoscute ca adevărat dumnezeiești. Căci toți redaseră aceleași lucruri în aceleași cuvinte și cu aceleași nume de la început până la sfârșit, așa încât păgânii au înțeles că Scripturile fuseseră traduse prin insuflarea lui Dumnezeu."},{"v":15,"t":"Și aceasta nu era nimic minunat pentru Dumnezeu să facă, El care, în robia poporului sub Nebucadnețar, când Scripturile fuseseră nimicite și iudeii se întorseseră în țara lor după șaptezeci de ani, a insuflat după aceea, în vremea lui Artaxerxe, regele perșilor, pe preotul Ezra, din seminția lui Levi, să povestească toate cuvintele proorocilor de mai înainte și să dea înapoi poporului legislația lui Moise. Acestea sunt cuvintele lui Irineu."}];
window.LIB_LAZY["eusebiu-istoria#119"]=[{"v":1,"t":"După ce Antonin fusese împărat nouăsprezece ani, Commod a primit cârmuirea. În primul lui an, Iulian a devenit episcop al bisericilor alexandrine, după ce Agripin ținuse slujba doisprezece ani."}];
window.LIB_LAZY["eusebiu-istoria#120"]=[{"v":1,"t":"Cam în acel timp, Pantaen, un om foarte distins prin învățătura lui, avea grija școlii credincioșilor din Alexandria. O școală de învățătură sfântă, care continuă până în zilele noastre, fusese înființată acolo în vremuri vechi și, după cum am fost înștiințați, era condusă de oameni de mare capacitate și râvnă pentru lucrurile dumnezeiești. Printre aceștia se povestește că Pantaen era în acel timp deosebit de vestit, fiind educat în sistemul filozofic al celor numiți stoici."},{"v":2,"t":"Se spune că a arătat o asemenea râvnă pentru Cuvântul dumnezeiesc încât a fost rânduit ca vestitor al Evangheliei lui Hristos către neamurile din Răsărit și a fost trimis până în India. Căci erau încă mulți evangheliști ai Cuvântului care căutau cu înfocare să-și folosească râvna insuflată, după pildele apostolilor, pentru sporirea și zidirea Cuvântului dumnezeiesc."},{"v":3,"t":"Pantaen era unul dintre aceștia și se spune că a mers în India. Se povestește că între persoanele de acolo care cunoșteau pe Hristos, a găsit Evanghelia după Matei, care îi precedase sosirea. Căci Bartolomeu, unul dintre apostoli, le predicase și le lăsase scrierea lui Matei în limba ebraică, pe care o păstraseră până în acel timp."},{"v":4,"t":"După multe fapte bune, Pantaen a ajuns în cele din urmă conducătorul școlii din Alexandria și a expus comorile învățăturii dumnezeiești și prin viu grai, și în scris."}];
window.LIB_LAZY["eusebiu-istoria#121"]=[{"v":1,"t":"În acest timp, Clement, fiind format împreună cu el în Scripturile dumnezeiești la Alexandria, a devenit bine cunoscut. Avea același nume cu cel care în vechime fusese în fruntea bisericii romane și care fusese ucenic al apostolilor."},{"v":2,"t":"În Hipotipozele lui vorbește de Pantaen pe nume ca de învățătorul lui. Mi se pare că se referă la aceeași persoană și în cartea întâi a Stromatelor lui, când, referindu-se la cei mai de seamă dintre urmașii apostolilor pe care îi întâlnise, spune:"},{"v":3,"t":"Această lucrare nu este o scriere alcătuită cu meșteșug pentru paradă; ci însemnările mele sunt strânse pentru bătrânețe, ca leac împotriva uitării; o icoană fără artă și o schiță grosolană a acelor cuvinte puternice și însuflețite pe care am avut privilegiul să le aud, precum și a unor oameni fericiți și cu adevărat vrednici de remarcat."},{"v":4,"t":"Dintre aceștia unul — cel ionian — era în Grecia, celălalt în Grecia Mare; unul dintre ei era din Celesiria, celălalt din Egipt. Mai erau alții în Răsărit, unul dintre ei asirian, celălalt evreu în Palestina. Dar când am dat de cel din urmă, — în capacitate era într-adevăr cel dintâi — după ce l-am vânat în ascunzătoarea lui din Egipt, am găsit odihnă."},{"v":5,"t":"Acești oameni, păstrând adevărata tradiție a învățăturii fericite, direct de la sfinții apostoli, Petru și Iacov și Ioan și Pavel, fiul primind-o de la tată (dar puțini erau ca părinții), au ajuns prin voia lui Dumnezeu chiar până la noi ca să depună acele semințe părintești și apostolice."}];
window.LIB_LAZY["eusebiu-istoria#122"]=[{"v":1,"t":"În acest timp Narcis era episcopul bisericii din Ierusalim și este prăznuit de mulți până în ziua de azi. Era al cincisprezecelea în succesiune de la asediul iudeilor sub Adrian. Am arătat că din acel timp biserica din Ierusalim a fost alcătuită întâi din neamuri, după cei din tăierea împrejur, și că Marcu a fost primul episcop dintre neamuri care a prezidat peste ei."},{"v":2,"t":"După el, succesiunea în episcopat a fost: întâi Casian; după el Publiu; apoi Maxim; după ei Iulian; apoi Gaiu; după el Simah și un alt Gaiu și iarăși un alt Iulian; după aceștia Capiton și Valens și Dolichian; și după toți aceștia Narcis, al treizecilea în succesiune regulată de la apostoli."}];
window.LIB_LAZY["eusebiu-istoria#123"]=[{"v":1,"t":"În acest timp, Rodon, un nativ al Asiei, care fusese învățat, după cum spune el însuși, de Tațian, pe care l-am cunoscut deja, scriind mai multe cărți, a publicat printre celelalte una împotriva ereziei lui Marcion. Spune că această erezie a fost împărțită în vremea lui în felurite păreri; și, descriind pe cei care au pricinuit dezbinarea, combate cu exactitate minciunile născocite de fiecare dintre ei."},{"v":2,"t":"Dar auzi ce scrie: De aceea și se dezbină între ei, susținând o părere neconsecventă. Căci Apeles, unul din turmă, mândrindu-se cu felul lui de viață și cu vârsta lui, recunoaște un singur principiu, dar spune că proorociile sunt de la un duh potrivnic, fiind dus la această părere de răspunsurile unei fecioare cu numele Filumena, care era stăpânită de un demon."},{"v":3,"t":"Dar alții, printre care Potit și Vasilic, țin la două principii, ca și marinarul Marcion însuși."},{"v":4,"t":"Aceștia urmând lupul din Pont și, ca el, neputând să pătrundă împărțirea lucrurilor, au devenit nechibzuiți și, fără să dea nicio dovadă, au afirmat două principii. Alții, iarăși, alunecând într-o rătăcire mai rea, socotesc că nu sunt numai două, ci trei firi. Dintre aceștia Sinerot este conducătorul și căpetenia, după cum spun cei care îi apără învățătura."},{"v":5,"t":"Același autor scrie că a avut o convorbire cu Apeles. Vorbește astfel: „Căci bătrânul Apeles, când vorbea cu noi, a fost combătut în multe lucruri pe care le spunea pe nedrept; de unde a spus și că nu este deloc necesar să-și cerceteze cineva învățătura, ci fiecare să continue să țină ce credea. Căci afirma că cei care se încred în Cel Răstignit se vor mântui, dacă numai vor fi găsiți făcând fapte bune. Dar, după cum am spus mai înainte, părerea lui despre Dumnezeu era cea mai întunecată dintre toate. Căci vorbea de un singur principiu, ca și învățătura noastră.”"},{"v":6,"t":"Apoi, după ce își expune pe larg propria părere, adaugă: Când i-am zis: Spune-mi cum știi aceasta sau cum poți afirma că este un singur principiu, a răspuns că proorociile se combat singure, pentru că nu au spus nimic adevărat; căci sunt neconsecvente și mincinoase și se contrazic. Dar cum este un singur principiu a spus că nu știe, ci că este doar încredințat de aceasta."},{"v":7,"t":"Când l-am conjurat atunci să spună adevărul, a jurat că îl spune când zicea că nu știe cum este un singur Dumnezeu nenăscut, ci că crede aceasta. La aceasta am râs și l-am mustrat pentru că, deși se numea învățător, nu știa cum să întărească ce învăța."},{"v":8,"t":"În aceeași lucrare, adresându-se lui Calistion, același scriitor recunoaște că fusese învățat la Roma de Tațian. Și spune că o carte de Probleme fusese pregătită de Tațian, în care făgăduia să explice părțile întunecate și ascunse ale Scripturilor dumnezeiești. Rodon însuși făgăduiește să dea într-o lucrare a lui soluțiile problemelor lui Tațian. Există și un Comentariu al lui la Hexaemeron."},{"v":9,"t":"Dar acest Apeles a scris multe, într-un chip nelegiuit, despre legea lui Moise, hulind cuvintele dumnezeiești în multe dintre lucrările lui, fiind, după cum se părea, foarte râvnitor pentru combaterea și răsturnarea lor. Atât despre aceștia."}];
window.LIB_LAZY["eusebiu-istoria#124"]=[{"v":1,"t":"Dușmanul Bisericii lui Dumnezeu, care este în chip hotărât un urâtor al binelui și un iubitor al răului și nu lasă neîncercat niciun fel de meșteșug împotriva oamenilor, a fost iarăși activ făcând să răsară erezii ciudate împotriva Bisericii. Căci unele persoane, ca niște reptile veninoase, s-au târât prin Asia și Frigia, lăudându-se că Montan este Mângâietorul și că femeile care îl urmau, Priscila și Maximila, erau prorocițe ale lui Montan."}];
window.LIB_LAZY["eusebiu-istoria#125"]=[{"v":1,"t":"Alții, dintre care Florin era căpetenia, au înflorit la Roma. El a căzut din prezbiteratul Bisericii și Blast a fost cuprins într-o cădere asemănătoare. Au tras și ei mulți din Biserică la părerea lor, fiecare silindu-se să introducă propriile lui înnoiri în privința adevărului."}];
window.LIB_LAZY["eusebiu-istoria#126"]=[{"v":1,"t":"Împotriva așa-numitei erezii frigiene, puterea care luptă totdeauna pentru adevăr a ridicat o armă tare și de neînvins, pe Apolinarie din Hierapole, pe care l-am pomenit mai înainte, și împreună cu el mulți alți oameni capabili, de la care a rămas material îndestulător pentru istoria noastră."},{"v":2,"t":"Unul dintre aceștia, la începutul lucrării lui împotriva lor, lasă mai întâi să se înțeleagă că s-a luptat cu ei în dispute rostite."},{"v":3,"t":"Își începe lucrarea în acest chip: După ce, o vreme foarte lungă și îndestulătoare, iubite Avircius Marcel, ai stăruit să scriu un tratat împotriva ereziei celor care se numesc după Miltiade, am șovăit până în timpul de față, nu din lipsă de capacitate de a combate minciuna sau de a da mărturie pentru adevăr, ci de teamă și neliniște ca nu cumva să par unora că fac adaosuri la învățăturile sau poruncile Evangheliei Noului Testament, la care este cu neputință ca cel care a ales să trăiască după Evanghelie nici să adauge, nici să scadă."},{"v":4,"t":"Dar aflându-mă de curând în Ancira Galatiei, am găsit biserica de acolo foarte agitată de această noutate, nu proorocie, cum o numesc ei, ci mai degrabă proorocie mincinoasă, după cum se va arăta. De aceea, cât am putut mai bine, cu ajutorul Domnului, am discutat în biserică multe zile despre acestea și alte lucruri aduse deosebit de ei înainte, așa încât biserica s-a bucurat și s-a întărit în adevăr, iar cei din partea opusă au fost pentru moment încurcați și potrivnicii s-au mâhnit."},{"v":5,"t":"Prezbiterii din loc, fiind de față și împreună-prezbiterul nostru Zotic din Otrus, ne-au cerut să lăsăm o însemnare a celor spuse împotriva potrivnicilor adevărului. Nu am făcut aceasta, dar am făgăduit să o scriem îndată ce ne va îngădui Domnul și să le-o trimitem curând."},{"v":6,"t":"După ce a spus aceasta, cu alte lucruri, la începutul lucrării sale, trece să arate pricina pomenitei erezii astfel: Împotrivirea lor și erezia lor recentă, care i-a despărțit de Biserică, s-a ridicat din următoarea pricină."},{"v":7,"t":"Se spune că este un sat numit Ardabau în acea parte a Misiei care se învecinează cu Frigia. Acolo întâi, se spune, când Grat era proconsul al Asiei, un nou convertit, cu numele Montan, prin dorința lui nestinsă de conducere, a dat potrivnicului prilej împotriva lui. Și a ieșit din fire și, fiind deodată într-un fel de frenezie și extaz, a delirat și a început să bolborosească și să rostească lucruri ciudate, proorocind într-un chip contrar obiceiului statornic al Bisericii transmis prin tradiție de la început."},{"v":8,"t":"Unii dintre cei care i-au auzit spusele false în acel timp s-au indignat și l-au mustrat ca pe unul stăpânit și aflat sub puterea unui demon și mânat de un duh înșelător și care tulbura mulțimea; și l-au oprit să vorbească, amintindu-și deosebirea făcută de Domnul și avertismentul Lui de a se păzi cu luare-aminte de venirea proorocilor mincinoși. (Matei 7:15) Dar alții, închipuindu-se stăpâniți de Duhul Sfânt și de un dar proorocesc, s-au înălțat și s-au umflat nu puțin; și uitând deosebirea Domnului, au provocat duhul nebun și viclean și amăgitor și au fost înșelați și amăgiți de el. În urma aceasta, nu a mai putut fi ținut în frâu ca să tacă."},{"v":9,"t":"Astfel, prin meșteșug, sau mai bine zis printr-un asemenea sistem de viclenie rea, diavolul, născocind nimicirea celor neascultători și fiind cinstit nevrednic de ei, le-a stârnit și le-a aprins pe ascuns mințile care se înstrăinaseră deja de credința adevărată. Și a stârnit pe lângă aceasta două femei și le-a umplut de duhul mincinos, așa încât vorbeau nebunește și fără rațiune și ciudat, ca persoana pomenită deja. Și duhul le declara fericite pe când se bucurau și se măreau în el și le umfla prin mărimea făgăduințelor lui. Dar uneori le mustra pe față într-un chip înțelept și credincios, ca să pară că este un mustrător. Dar cei dintre frigieni care fuseseră amăgiți erau puțini la număr. Și duhul arogant i-a învățat să defaime toată Biserica universală de sub cer, pentru că duhul proorociei mincinoase nu primea de la ea nici cinste, nici intrare în ea."},{"v":10,"t":"Căci credincioșii din Asia s-au adunat adesea în multe locuri prin toată Asia ca să cerceteze această chestiune și au examinat spusele noi și le-au declarat nesfințite și au respins erezia și astfel aceste persoane au fost izgonite din Biserică și oprite de la împărtășanie."},{"v":11,"t":"După ce a povestit aceste lucruri la început și a continuat combaterea amăgirii lor în toată lucrarea, în cartea a doua vorbește astfel despre sfârșitul lor:"},{"v":12,"t":"De vreme ce, deci, ne-au numit ucigași de proroci pentru că nu am primit proorocii lor vorbăreți, care, spun ei, sunt cei pe care i-a făgăduit Domnul că îi va trimite poporului (Matei 23:34), să răspundă ca în prezența lui Dumnezeu: Cine este, o, prieteni, dintre acești care au început să vorbească, de la Montan și femeile încoace, care să fi fost prigonit de iudei sau omorât de oameni fără lege? Nimeni. Sau a fost vreunul dintre ei prins și răstignit pentru Nume? Cu adevărat nu. Sau a fost vreuna dintre aceste femei biciuită vreodată în sinagogile iudeilor sau ucisă cu pietre? Nu; niciodată nicăieri."},{"v":13,"t":"Dar printr-un alt fel de moarte se spune că au murit Montan și Maximila. Căci se povestește că, stârniți de duhul freneziei, s-au spânzurat amândoi; nu în același timp, ci în timpul pe care zvonul obștesc îl dă pentru moartea fiecăruia. Și astfel au murit și și-au încheiat viețile ca trădătorul Iuda."},{"v":14,"t":"Tot așa, după cum spune zvonul general, acea persoană remarcabilă, primul, ca să zic așa, administrator al așa-numitei lor proorocii, un anume Teodot — care, ca și cum ar fi fost într-un timp luat și primit la cer, a căzut în transe și s-a încredințat duhului înșelător — a fost aruncat ca un disc și a murit nenorocit."},{"v":15,"t":"Se spune că aceste lucruri s-au întâmplat în acest chip. Dar cum nu le-am văzut, prietene, nu ne prefacem că le știm. Poate într-un asemenea chip, poate nu, au murit Montan și Teodot și pomenita femeie."},{"v":16,"t":"Spune iarăși în aceeași carte că sfinții episcopi ai acelui timp au încercat să combată duhul din Maximila, dar au fost împiedicați de alții care lucrau vădit împreună cu duhul."},{"v":17,"t":"Scrie astfel: „Și să nu spună duhul, în aceeași lucrare a lui Asterie Urban, prin Maximila: «Sunt alungat de la oi ca un lup. Nu sunt lup. Sunt cuvânt și duh și putere.» Ci să arate limpede și să dovedească puterea din duh. Și prin duh să-i silească să-l mărturisească pe cei care erau atunci de față cu scopul de a încerca și a discuta cu duhul vorbăreț, — acei oameni de seamă și episcopi, Zotic, din satul Comana, și Iulian, din Apameea, a căror gură au astupat-o urmașii lui Temison, refuzând să îngăduie ca duhul mincinos și amăgitor să fie combătut de ei.”"},{"v":18,"t":"Iarăși în aceeași lucrare, după ce spune alte lucruri în combaterea proorociilor mincinoase ale Maximilei, arată vremea în care a scris aceste povestiri și pomenește prezicerile ei în care prorocea războaie și anarhie. Falsitatea lor o condamnă în felul următor:"},{"v":19,"t":"„Și nu s-a arătat limpede că este mincinos aceasta? Căci astăzi sunt mai mult de treisprezece ani de când a murit femeia și nu a fost nici război parțial, nici general în lume; ci, mai degrabă, prin îndurarea lui Dumnezeu, pace neîntreruptă chiar și pentru creștini.” Aceste lucruri sunt luate din cartea a doua."},{"v":20,"t":"Voi adăuga și scurte extrase din cartea a treia, în care vorbește astfel împotriva laudelor lor că mulți dintre ei au suferit martiriul: Când, deci, sunt încurcați, fiind combătuți în tot ce spun, încearcă să se adăpostească la martirii lor, pretinzând că au mulți martiri și că aceasta este dovadă sigură a puterii așa-numitului duh proorocesc care este cu ei. Dar aceasta, după cum se pare, este în întregime înșelătoare."},{"v":21,"t":"Căci unele dintre erezii au foarte mulți martiri; dar cu siguranță nu ne vom învoi din această pricină cu ei și nu vom mărturisi că ei țin adevărul. Și, mai întâi, într-adevăr, cei numiți marcioniți, din erezia lui Marcion, spun că au o mulțime de martiri pentru Hristos; totuși nu mărturisesc pe Hristos însuși în adevăr. Puțin mai departe continuă:"},{"v":22,"t":"„Când cei chemați la martiriu din Biserică pentru adevărul credinței au întâlnit pe vreunul dintre așa-numiții martiri ai ereziei frigiene, s-au despărțit de ei și au murit fără nicio părtășie cu ei, pentru că nu au voit să-și dea încuviințarea duhului lui Montan și al femeilor. Și că aceasta este adevărat și s-a întâmplat în vremea noastră în Apameea pe Meandru, printre cei care au suferit martiriul cu Gaiu și Alexandru din Eumenia, este bine cunoscut.”"}];
window.LIB_LAZY["eusebiu-istoria#127"]=[{"v":1,"t":"În această lucrare pomenește un scriitor, Miltiade, spunând că și el a scris o carte împotriva pomenitei erezii. După ce citează unele dintre cuvintele lor, adaugă: „Găsind aceste lucruri într-o anume lucrare a lor în potrivnicie cu lucrarea fratelui Alcibiade, în care arată că un prooroc nu trebuie să vorbească în extaz, am făcut un rezumat.”"},{"v":2,"t":"Puțin mai departe, în aceeași lucrare, dă o listă a celor care au prorocit sub noul legământ, printre care înșiră un anume Ammia și Cuadrat, spunând: Dar proorocul mincinos cade într-un extaz, în care este fără rușine și teamă. Începând cu neștiința voită, trece, după cum s-a spus, la nebunia involuntară a sufletului."},{"v":3,"t":"Ei nu pot arăta că vreunul dintre proorocii vechi sau noi a fost astfel purtat în duh. Nici nu se pot lăuda cu Agab, sau Iuda, sau Sila, sau fiicele lui Filip, sau Ammia din Filadelfia, sau Cuadrat, sau alții care nu le aparțin."},{"v":4,"t":"Și iarăși, după puțin, spune: „Căci dacă după Cuadrat și Ammia din Filadelfia, după cum afirmă ei, femeile cu Montan au primit darul proorocesc, să arate cine dintre ei l-a primit de la Montan și femei. Căci apostolul a socotit necesar ca darul proorocesc să continue în toată Biserica până la venirea de pe urmă. Dar ei nu pot arăta aceasta, deși acesta este al paisprezecelea an de la moartea Maximilei.”"},{"v":5,"t":"Scrie astfel. Dar Miltiade, la care se referă, a lăsat alte monumente ale propriei lui râvne pentru Scripturile Dumnezeiești, în cuvântările pe care le-a alcătuit împotriva grecilor și împotriva iudeilor, răspunzând fiecăruia dintre ei deosebit în două cărți. Și pe lângă aceasta adresează o apologie cârmuitorilor pământești, în folosul filozofiei pe care a îmbrățișat-o."}];
window.LIB_LAZY["eusebiu-istoria#128"]=[{"v":1,"t":"Cum așa-numita erezie frigiană înflorea încă în Frigia în vremea lui, Apoloniu, de asemenea un scriitor bisericesc, a întreprins combaterea ei și a scris o lucrare deosebită împotriva ei, îndreptând în amănunt proorociile mincinoase care circulau între ei și mustrând viața întemeietorilor ereziei. Dar auzi propriile lui cuvinte despre Montan:"},{"v":2,"t":"„Faptele lui și învățătura lui arată cine este acest nou învățător. Acesta este cel care a învățat desfacerea căsătoriei; care a făcut legi pentru post; care a numit Pepuza și Timion, orășele din Frigia, Ierusalim, voind să adune oameni la ele din toate părțile; care a rânduit strângători de bani; care a născocit primirea de daruri sub numele de prinoase; care a rânduit solde pentru cei care predicau învățătura lui, ca învățătura lui să biruie prin lăcomia pântecelui.”"},{"v":3,"t":"Scrie astfel despre Montan; și puțin mai departe scrie următoarele despre prorocițele lui: „Arătăm că aceste prime prorocițe însele, de îndată ce au fost umplute de duh, și-au părăsit soții. Cât de mincinos vorbesc, deci, cei care o numesc pe Prisca fecioară.”"},{"v":4,"t":"După aceea spune: „Nu vi se pare că toată Scriptura oprește pe un prooroc să primească daruri și bani? Când, deci, văd pe proorocită primind aur și argint și veșminte scumpe, cum pot ocoli să o mustru?”"},{"v":5,"t":"Și iarăși, puțin mai departe, vorbește astfel despre unul dintre mărturisitorii lor: „Astfel și Temison, care era îmbrăcat cu o lăcomie plauzibilă, nu a putut îndura semnul mărturisirii, ci a lepădat lanțurile pentru belșug de averi. Totuși, deși ar fi trebuit să fie smerit din această pricină, a cutezat să se laude ca martir și, în imitarea apostolului, a scris o anume epistolă catolică, ca să-i învețe pe cei a căror credință era mai bună decât a lui, luptând pentru cuvinte cu sunet gol și hulind împotriva Domnului și a apostolilor și a sfintei Biserici.”"},{"v":6,"t":"Și iarăși despre alții dintre cei cinstiți între ei ca martiri, scrie astfel: Ca să nu vorbesc de mulți, să ne spună însăși proorocița despre Alexandru, care se numea martir, cu care obișnuiește să ospăteze și căruia i se închină mulți. Nu avem nevoie să pomenim jafurile lui și alte fapte îndrăznețe pentru care a fost pedepsit, dar arhivele le cuprind."},{"v":7,"t":"Care dintre aceștia iartă păcatele celuilalt? Iartă proorocul jafurile martirului sau martirul lăcomia proorocului? Căci deși Domnul a zis: «Să nu vă luați nici aur, nici argint, nici două haine» (Matei 10:9-10), acești oameni, în deplină opoziție, încalcă în privința posesiunii lucrurilor oprite. Căci vom arăta că cei pe care îi numesc proroci și martiri își adună câștigul nu numai de la oameni bogați, ci și de la cei săraci și orfani și văduve."},{"v":8,"t":"Dar dacă sunt încrezători, să se ridice și să discute aceste lucruri, ca, dacă sunt dovediți, să înceteze de acum înainte să încalce. Căci rodurile proorocului trebuie încercate; «căci pomul se cunoaște după roadă». (Matei 12:33)"},{"v":9,"t":"Dar ca cei care vor să știe despre Alexandru, el a fost judecat de Aemilius Frontin, proconsul la Efes; nu din pricina Numelui, ci pentru jafurile pe care le făcuse, fiind deja apostat. După aceea, declarând pe nedrept pentru numele Domnului, a fost eliberat, amăgind pe credincioșii care erau acolo. Și propria lui parohie, din care venea, nu l-a primit, pentru că era tâlhar. Cei care vor să afle despre el au înscrisurile publice ale Asiei. Și totuși proorocul cu care a petrecut mulți ani nu știe nimic despre el!"},{"v":10,"t":"Dezvăluindu-l pe el, prin el dezvăluim și prefăcătoria proorocului. Am putea arăta același lucru despre mulți alții. Dar dacă sunt încrezători, să îndure încercarea."},{"v":11,"t":"Iarăși, într-o altă parte a lucrării sale, vorbește astfel despre proorocii cu care se laudă: „Dacă tăgăduiesc că proorocii lor au primit daruri, să recunoască aceasta: că dacă sunt dovediți că le primesc, nu sunt proroci. Și vom aduce o mulțime de dovezi pentru aceasta. Dar este necesar ca toate rodurile unui prooroc să fie cercetate. Spuneți-mi, își vopsește un prooroc părul? Își vopsește un prooroc genele? Se desfată un prooroc cu podoabe? Se joacă un prooroc cu table și zaruri? Dă un prooroc cu camătă? Să mărturisească dacă aceste lucruri sunt îngăduite sau nu; dar eu voi arăta că au fost făcute de ei.”"},{"v":12,"t":"Același Apoloniu spune în aceeași lucrare că, la vremea scrierii lui, era al patruzecilea an de când Montan începuse pretinsa lui proorocie."},{"v":13,"t":"Și spune și că Zotic, care a fost pomenit de scriitorul dinainte, când Maximila se prefăcea că prorocește în Pepuza, i-a stat împotrivă și s-a silit să combată duhul care lucra în ea; dar a fost împiedicat de cei care se învoiau cu ea. Pomenește și pe un anume Trasea printre martirii acelui timp. Vorbește, pe lângă aceasta, de o tradiție că Mântuitorul a poruncit apostolilor Săi să nu plece din Ierusalim doisprezece ani. Se slujește și de mărturii din Descoperirea lui Ioan și povestește că un mort a fost înviat, prin puterea dumnezeiască, de Ioan însuși la Efes. Adaugă și alte lucruri prin care dezvăluie pe deplin și din belșug rătăcirea ereziei despre care am vorbit. Acestea sunt chestiunile însemnate de Apoloniu."}];
window.LIB_LAZY["eusebiu-istoria#129"]=[{"v":1,"t":"Serapion, care, după cum se spune, i-a urmat în acel timp lui Maximin ca episcop al bisericii din Antiohia, pomenește lucrările lui Apolinarie împotriva pomenitei erezii. Și se referă la el într-o scrisoare privată către Caric și Pontiu, în care el însuși dezvăluie aceeași erezie și adaugă următoarele cuvinte:"},{"v":2,"t":"„Ca să vedeți că faptele acestei cete mincinoase a așa-numitei proorocii noi sunt o urâciune pentru toată frăția din toată lumea, v-am trimis scrierile preafericitului Claudiu Apolinarie, episcopul Hierapolei din Asia.”"},{"v":3,"t":"În aceeași scrisoare a lui Serapion se găsesc semnăturile mai multor episcopi, dintre care unul se subscrie astfel: „Eu, Aurelius Cirenius, martor, mă rog pentru sănătatea voastră.” Și un altul în acest chip: „Aelius Publius Iulius, episcop al Debeltumului, o colonie a Traciei. Precum Dumnezeu trăiește în ceruri, fericitul Sotas din Anhialos a voit să scoată demonul din Priscila, dar fățarnicii nu l-au lăsat.”"},{"v":4,"t":"Și semnăturile autografe ale multor alți episcopi care se învoiau cu ei sunt cuprinse în aceeași scrisoare. Atât despre aceste persoane."}];
window.LIB_LAZY["eusebiu-istoria#130"]=[{"v":1,"t":"Irineu a scris mai multe scrisori împotriva celor care tulburau rânduiala sănătoasă a Bisericii de la Roma. Una dintre ele era către Blast, Despre schismă; alta către Florin, Despre monarhie sau Că Dumnezeu nu este autorul răului. Căci Florin părea că apără această părere. Și pentru că era tras de rătăcirea lui Valentin, Irineu a scris lucrarea lui Despre Ogdoadă, în care arată că el însuși cunoscuse pe cei dintâi urmași ai apostolilor."},{"v":2,"t":"La încheierea tratatului am găsit o notă foarte frumoasă pe care ne simțim siliți să o inserăm în această lucrare. Sună astfel: „Vă conjur pe voi care veți copia această carte, prin Domnul nostru Isus Hristos și prin slăvita Lui venire când va veni să judece vii și morți, să comparați ce veți scrie și să corectați cu grijă după acest manuscris și să scrieți și această conjurare și să o puneți în copie.”"},{"v":3,"t":"Aceste lucruri se pot citi cu folos în lucrarea lui și povestite de noi, ca să avem pe acei oameni din vechime și cu adevărat sfinți drept cea mai bună pildă de grijă osârduitoare."},{"v":4,"t":"În scrisoarea către Florin, despre care am vorbit, Irineu pomenește din nou apropierea lui de Policarp, spunând: Aceste învățături, o, Florine, ca să vorbesc blând, nu sunt de judecată sănătoasă. Aceste învățături sunt în neînvoire cu Biserica și duc în cea mai mare nelegiuire pe cei care le primesc. Aceste învățături nici măcar ereticii din afara Bisericii nu au cutezat vreodată să le publice. Aceste învățături prezbiterii care au fost înaintea noastră și care au fost tovarășii apostolilor nu ți le-au transmis."},{"v":5,"t":"Căci când eram băiat, te-am văzut în Asia de jos, cu Policarp, mișcându-te cu strălucire la curtea împărătească și silindu-te să-i câștigi încuviințarea."},{"v":6,"t":"Îmi amintesc întâmplările acelui timp mai limpede decât pe cele din anii recenți. Căci ce învață băieții, crescând cu mintea lor, se unește cu ea; așa încât pot descrie chiar locul în care ședea fericitul Policarp când vorbea și ieșirile și intrările lui și felul vieții lui și înfățișarea lui trupească și cuvântările lui către popor și povestirile pe care le dădea despre împărtășirea lui cu Ioan și cu ceilalți care văzuseră pe Domnul. Și cum își amintea cuvintele lor și ce auzise de la ei despre Domnul și despre minunile Lui și despre învățătura Lui, primindu-le de la martori oculari ai «Cuvântului vieții» (1 Ioan 1:1), Policarp povestea toate lucrurile în armonie cu Scripturile."},{"v":7,"t":"Aceste lucruri fiindu-mi spuse prin îndurarea lui Dumnezeu, le-am ascultat cu luare-aminte, însemnându-le nu pe hârtie, ci în inima mea. Și necontenit, prin harul lui Dumnezeu, mi le amintesc cu credincioșie. Și pot mărturisi înaintea lui Dumnezeu că dacă acel fericit și apostolic prezbiter ar fi auzit vreun asemenea lucru, ar fi strigat și și-ar fi astupat urechile și, după obiceiul lui, ar fi exclamat: O, Dumnezeule bun, la ce vremuri m-ai cruțat ca să îndur aceste lucruri? Și ar fi fugit din locul unde, șezând sau stând, auzise asemenea cuvinte."},{"v":8,"t":"Și aceasta se poate arăta limpede din scrisorile pe care le-a trimis, fie bisericilor învecinate pentru întărirea lor, fie unora dintre frați, mustrându-i și îndemnându-i. Până aici Irineu."}];
window.LIB_LAZY["eusebiu-istoria#131"]=[{"v":1,"t":"Cam în același timp, în domnia lui Comod, starea noastră s-a îmbunătățit și, prin harul lui Dumnezeu, bisericile din toată lumea se bucurau de pace, iar cuvântul mântuirii ducea fiecare suflet, din orice neam de oameni, la închinarea cucernică înaintea Dumnezeului universului. Așa încât acum, la Roma, mulți dintre cei foarte însemnați prin bogăție și neam s-au întors spre mântuirea lor, cu toată casa și rudele lor."},{"v":2,"t":"Dar demonul care urăște binele, fiind rău din fire, nu a putut îndura aceasta, ci s-a pregătit din nou de luptă, născocind multe uneltiri împotriva noastră. Și l-a adus la judecată pe Apoloniu, din cetatea Romei, un om vestit între credincioși prin învățătură și filozofie, ațâțând împotriva lui, ca să-l acuze, pe unul dintre slujitorii săi, potrivit pentru o astfel de faptă."},{"v":3,"t":"Dar acest nenorocit a adus acuzația într-un ceas nepotrivit, fiindcă printr-o poruncă împărătească nu era îngăduit să trăiască denunțătorii unor asemenea lucruri. Și i-au fost zdrobite îndată picioarele, judecătorul Perenniu rostind această sentință împotriva lui."},{"v":4,"t":"Dar martirul, mult iubit de Dumnezeu, fiind rugat stăruitor și cerut de judecător să dea socoteală de sine înaintea Senatului, a rostit în fața tuturor o apărare grăitoare a credinței pentru care mărturisea. Și, ca printr-o hotărâre a Senatului, a fost omorât prin tăierea capului, o lege străveche cerând ca cei aduși la judecată și care refuză să se lepede să nu fie eliberați. Cine dorește să cunoască argumentele lui în fața judecătorului și răspunsurile lui la întrebările lui Perenniu și toată apărarea lui înaintea Senatului le va găsi în însemnările vechilor martiri pe care le-am adunat."}];
window.LIB_LAZY["eusebiu-istoria#132"]=[{"v":1,"t":"În al zecelea an al domniei lui Comod, Victor l-a urmat pe Eleuter, acesta din urmă ținând episcopia timp de treisprezece ani. În același an, după ce Iulian își încheiase al zecelea an, Dimitrie a primit purtarea de grijă a parohiilor din Alexandria. În acest timp, pomenitul Serapion, al optulea de la apostoli, era încă cunoscut ca episcop al bisericii din Antiohia. Teofil păstorea la Cezareea Palestinei, iar Narcis, pe care l-am pomenit mai înainte, avea încă grija bisericii din Ierusalim. Bachil era în același timp episcop al Corintului din Grecia, iar Policrat al parohiei din Efes. Și pe lângă aceștia, o mulțime de alții, cum e firesc, erau atunci însemnați. Dar noi am dat numai numele celor a căror dreptate a credinței a ajuns până la noi în scris."}];
window.LIB_LAZY["eusebiu-istoria#133"]=[{"v":1,"t":"O întrebare de nu mică însemnătate s-a ridicat atunci. Căci parohiile din toată Asia, ca dintr-o tradiție mai veche, socoteau că ziua a paisprezecea a lunii, zi în care iudeilor li se poruncise să jertfească mielul, trebuie ținută ca sărbătoare a Paștilor Mântuitorului. Era deci necesar să-și încheie postul în acea zi, oricare ar fi fost ziua săptămânii. Dar nu era obiceiul bisericilor din restul lumii să-l încheie în acest timp, ele ținând rânduiala care, din tradiția apostolică, a stăpânit până în ziua de azi, de a încheia postul în nicio altă zi decât în aceea a învierii Mântuitorului nostru."},{"v":2,"t":"Din această pricină s-au ținut sinoade și adunări de episcopi și toți, într-un singur gând, prin schimb de scrisori, au alcătuit o hotărâre bisericească: taina învierii Domnului să nu fie sărbătorită în nicio altă zi decât în ziua Domnului și să păzim sfârșitul postului pascal numai în această zi. Se află încă o scriere a celor care s-au adunat atunci în Palestina, în fruntea cărora erau Teofil, episcopul Cezareei, și Narcis, episcopul Ierusalimului. Și mai este o altă scriere a celor adunați la Roma pentru aceeași întrebare, care poartă numele episcopului Victor; precum și a episcopilor din Pont, în fruntea cărora stătea Palma, ca cel mai vârstnic; a parohiilor din Galia, al căror episcop era Irineu, și a celor din Osroene și din cetățile de acolo; și o scrisoare personală a lui Bachil, episcopul bisericii din Corint, și a foarte multor alții, care au rostit aceeași părere și judecată și au dat același vot."},{"v":3,"t":"Și cele înfățișate mai sus au fost hotărârea lor unanimă."}];
window.LIB_LAZY["eusebiu-istoria#134"]=[{"v":1,"t":"Dar episcopii din Asia, în frunte cu Policrat, au hotărât să se țină de obiceiul vechi transmis lor. El însuși, într-o scrisoare adresată lui Victor și bisericii din Roma, a expus în aceste cuvinte tradiția care ajunsese la el:"},{"v":2,"t":"Noi păzim ziua exactă, fără să adăugăm și fără să scădem. Căci și în Asia au adormit mari luminători, care vor învia în ziua venirii Domnului, când va veni cu slavă din cer și va căuta pe toți sfinții. Printre aceștia sunt Filip, unul dintre cei doisprezece apostoli, care a adormit în Hierapole, și cele două fiice ale lui, fecioare bătrâne, și o altă fiică, care a trăit în Duhul Sfânt și se odihnește acum la Efes; și, încă, Ioan, care a fost și martor, și învățător, care s-a rezemat pe pieptul Domnului și, fiind preot, a purtat placa preoțească."},{"v":3,"t":"El a adormit la Efes."},{"v":4,"t":"Și Policarp din Smirna, care a fost episcop și martir; și Trasea, episcop și martir din Eumenia, care a adormit în Smirna."},{"v":5,"t":"De ce să mai pomenesc pe episcopul și martirul Sagaris, care a adormit în Laodiceea, sau pe fericitul Papirie, sau pe Melito, famenul, care a trăit cu totul în Duhul Sfânt și zace în Sardes, așteptând cercetarea din cer, când va învia din morți?"},{"v":6,"t":"Toți aceștia au păzit ziua a paisprezecea a Paștilor după Evanghelie, nealunecând întru nimic, ci urmând canonul credinței. Și eu, Policrat, cel mai mic dintre voi toți, fac după tradiția rudelor mele, pe unii dintre care i-am urmat îndeaproape. Căci șapte dintre rudele mele au fost episcopi și eu sunt al optulea. Și rudele mele au păzit totdeauna ziua în care poporul scotea aluatul."},{"v":7,"t":"Eu, deci, fraților, care am trăit șaizeci și cinci de ani în Domnul și m-am întâlnit cu frații din toată lumea și am străbătut toată Sfânta Scriptură, nu mă înspăimânt de cuvinte înfricoșătoare. Căci cei mai mari decât mine au spus: «Trebuie să ascultăm de Dumnezeu mai mult decât de oameni.» (Fapte 5:29)"},{"v":8,"t":"Apoi scrie despre toți episcopii care erau de față cu el și gândeau ca el. Cuvintele lui sunt acestea: „Aș putea pomeni pe episcopii care au fost de față, pe care i-am chemat la dorința voastră; ale căror nume, de le-aș scrie, ar alcătui o mare mulțime. Și ei, văzând mărunțimea mea, și-au dat încuviințarea scrisorii, știind că nu mi-am purtat în zadar perii albi, ci întotdeauna mi-am cârmuit viața după Domnul Isus.”"},{"v":9,"t":"Atunci Victor, care păstorea biserica din Roma, a încercat îndată să taie de la unitatea comună parohiile din toată Asia, împreună cu bisericile care se învoiau cu ele, ca fiind de altă credință; și a scris scrisori și i-a declarat pe toți frații de acolo cu totul excomunicați."},{"v":10,"t":"Dar aceasta nu a plăcut tuturor episcopilor. Și l-au rugat să se gândească la cele ale păcii, ale unității și iubirii dintre vecini. Se păstrează cuvinte de-ale lor, mustrându-l aspru pe Victor."},{"v":11,"t":"Printre ei era Irineu, care, trimițând scrisori în numele fraților din Galia pe care îi păstorea, a susținut că taina învierii Domnului trebuie păzită numai în ziua Domnului. Îl îndeamnă cuviincios pe Victor să nu taie biserici întregi ale lui Dumnezeu, care păzeau tradiția unui obicei străvechi, și, după multe alte cuvinte, merge mai departe astfel:"},{"v":12,"t":"Căci controversa nu privește numai ziua, ci și însuși felul postului. Unii socotesc că trebuie să postească o zi, alții două, alții mai multe; unii, încă, își socotesc ziua ca alcătuită din patruzeci de ore, zi și noapte."},{"v":13,"t":"Și această varietate în păzire nu a început în timpul nostru, ci cu mult înainte, în al strămoșilor noștri. Este de crezut că ei nu s-au ținut de o strictă exactitate și astfel au format un obicei pentru urmașii lor, după simplitatea lor și felul lor deosebit. Totuși, toți aceștia au trăit nu mai puțin în pace, iar și noi trăim în pace unii cu alții; și neînțelegerea privind postul întărește învoirea în credință."},{"v":14,"t":"Adaugă la aceasta următoarea povestire, pe care o pot insera cu dreptate: Printre aceștia au fost prezbiterii dinaintea lui Soter, care au păstorit biserica pe care o cârmuiți acum. Vorbim de Anicet și Pius și Higin și Telesfor și Xyst. Ei nici nu au păzit-o ei înșiși, nici nu au îngăduit celor de după ei să o facă. Și totuși, deși nu o păzeau, erau în pace cu cei care veneau la ei din parohiile unde era păzită; deși această păzire era mai potrivnică celor care nu o păzeau."},{"v":15,"t":"Dar nimeni nu a fost vreodată izgonit pentru această formă; ci prezbiterii dinaintea ta, care nu o păzeau, trimiteau euharistia celor din alte parohii care o păzeau."},{"v":16,"t":"Și când fericitul Policarp a fost la Roma, în vremea lui Anicet, și au avut mici neînțelegeri în privința altor lucruri, s-au împăcat îndată unul cu altul, nevrând să se certe pentru această chestiune. Căci nici Anicet nu a putut să-l convingă pe Policarp să nu păzească ceea ce păzise totdeauna cu Ioan, ucenicul Domnului nostru, și cu ceilalți apostoli cu care se însoțise; nici Policarp nu a putut să-l convingă pe Anicet să o păzească, deoarece acesta spunea că trebuie să urmeze obiceiurile prezbiterilor dinaintea lui."},{"v":17,"t":"Dar, deși lucrurile stăteau astfel, s-au împărtășit împreună, iar Anicet a lăsat lui Policarp săvârșirea euharistiei în biserică, vădit ca semn de cinste. Și s-au despărțit unul de altul în pace, atât cei care păzeau, cât și cei care nu păzeau, păstrând pacea întregii biserici."},{"v":18,"t":"Astfel Irineu, care cu adevărat își merita numele, a devenit făcător de pace în această privință, îndemnând și tratând în acest chip pentru pacea bisericilor. Și a discutat în scris această întrebare dezbătută nu numai cu Victor, ci și cu cei mai mulți dintre ceilalți conducători ai bisericilor."}];
window.LIB_LAZY["eusebiu-istoria#135"]=[{"v":1,"t":"Cei din Palestina pe care i-am pomenit de curând, Narcis și Teofil, și împreună cu ei Cassiu, episcopul bisericii din Tir, și Clar al bisericii din Ptolemaida, și cei care s-au adunat cu ei, după ce au spus multe despre tradiția privind Paștile, care le venise prin succesiune de la apostoli, adaugă la încheierea scrisorii lor aceste cuvinte:"},{"v":2,"t":"„Străduiți-vă să trimiteți copii ale scrisorii noastre fiecărei biserici, ca să nu dăm prilej celor care își amăgesc ușor sufletele. Vă arătăm, într-adevăr, că și în Alexandria o țin în aceeași zi ca noi. Căci scrisori sunt purtate de la noi la ei și de la ei la noi, așa încât în același chip și în același timp ținem ziua sfântă.”"}];
window.LIB_LAZY["eusebiu-istoria#136"]=[{"v":1,"t":"Pe lângă lucrările și scrisorile lui Irineu pe care le-am pomenit, se păstrează o carte a lui, Despre cunoaștere, scrisă împotriva grecilor, foarte concisă și remarcabil de puternică; și alta, pe care a închinat-o unui frate, Marcian, Spre dovedirea propovăduirii apostolice; și un volum cuprinzând diverse Dizertații, în care pomenește Epistola către Evrei și așa-numita Înțelepciune a lui Solomon, citând din ele. Acestea sunt lucrările lui Irineu care au ajuns la cunoștința noastră."},{"v":2,"t":"Comod și-a încheiat domnia după treisprezece ani, iar Sever a devenit împărat în mai puțin de șase luni după moartea lui, Pertinax domnind în timpul dintre ei."}];
window.LIB_LAZY["eusebiu-istoria#137"]=[{"v":1,"t":"Numeroase amintiri ale râvnei credincioase a vechilor bărbați bisericești din acel timp sunt încă păstrate de mulți. Dintre ele vrem să semnalăm în mod deosebit scrierile lui Heraclit Despre Apostol și pe cele ale lui Maxim despre întrebarea atât de dezbătută între eretici, Obârșia răului, și despre Facerea materiei. De asemenea, pe cele ale lui Candid despre Hexaemeron și ale lui Apion despre același subiect; precum și ale lui Sextus Despre înviere și un alt tratat al lui Arabian, și scrierile unei mulțimi de alții, în privința cărora, pentru că nu avem date, este cu neputință să spunem în lucrarea noastră când au trăit sau să dăm vreo relatare despre istoria lor. Și au ajuns la noi lucrările multor altora ale căror nume nu le putem da, ortodocși și bisericești, după cum arată tâlcuirile lor ale dumnezeieștilor Scripturi, dar necunoscuți nouă, pentru că numele lor nu sunt arătate în scrierile lor."}];
window.LIB_LAZY["eusebiu-istoria#138"]=[{"v":1,"t":"Într-o lucrare osârduitoare a unuia dintre acești scriitori, împotriva ereziei lui Artemon, pe care Pavel din Samosata a încercat să o învie din nou în zilele noastre, se află o relatare potrivită istoriei pe care o cercetăm acum."},{"v":2,"t":"Căci el critică, drept o noutate târzie, pomenita erezie care învață că Mântuitorul a fost un simplu om, fiindcă încercau să o înalțe ca veche. După ce a dat în lucrarea sa multe alte argumente în combaterea minciunii lor hulitoare, adaugă următoarele cuvinte:"},{"v":3,"t":"Căci ei spun că toți învățătorii dintâi și apostolii au primit și au învățat ceea ce ei declară acum și că adevărul Evangheliei a fost păstrat până în vremea lui Victor, care a fost al treisprezecelea episcop al Romei de la Petru, dar că de la urmașul lui, Zefirin, adevărul a fost stricat."},{"v":4,"t":"Și ceea ce spun ei ar putea fi plauzibil, dacă mai întâi dumnezeieștile Scripturi nu i-ar contrazice. Și există scrieri ale unor frați mai vechi decât vremea lui Victor, pe care le-au scris în apărarea adevărului împotriva păgânilor și împotriva ereziilor care existau în zilele lor. Mă refer la Iustin și Miltiade și Tațian și Clement și mulți alții, în toate lucrările cărora Hristos este vorbit ca Dumnezeu."},{"v":5,"t":"Căci cine nu cunoaște lucrările lui Irineu și ale lui Melito și ale altora, care învață că Hristos este Dumnezeu și om? Și câți psalmi și imnuri, scrise de frații credincioși de la început, cântă pe Hristos, Cuvântul lui Dumnezeu, vorbind despre El ca despre dumnezeiesc."},{"v":6,"t":"Cum, deci, de vreme ce părerea ținută de Biserică a fost propovăduită atâția ani, ar fi putut propovăduirea ei să fie amânată, cum afirmă ei, până în vremea lui Victor? Și cum nu se rușinează să vorbească atât de mincinos despre Victor, știind bine că el l-a tăiat de la împărtășanie pe Teodot cizmarul, căpetenia și părintele acestei apostazii lepădătoare de Dumnezeu și cel dintâi care a declarat că Hristos este simplu om? Căci dacă Victor se învoia cu părerile lor, cum spune bârfa lor, cum de l-a izgonit pe Teodot, născocitorul acestei erezii?"},{"v":7,"t":"Atât despre Victor. Episcopia lui a durat zece ani, iar Zefirin a fost rânduit urmașul lui cam în al nouălea an al domniei lui Sever. Autorul pomenitei cărți, despre întemeietorul acestei erezii, povestește o altă întâmplare petrecută în vremea lui Zefirin, folosind aceste cuvinte:"},{"v":8,"t":"Voi aminti multor frați un fapt petrecut în vremea noastră, care, dacă s-ar fi întâmplat în Sodoma, ar fi putut, cred, să le fie o prevenire. Era un mărturisitor, Natalie, nu de mult, ci în zilele noastre."},{"v":9,"t":"Acest om a fost amăgit odată de Asclepiodot și de un alt Teodot, un schimbător de bani. Amândoi erau ucenici ai lui Teodot cizmarul, care, cum am spus, a fost cel dintâi excomunicat de Victor, episcopul de atunci, din pricina acestei păreri, sau mai bine zis nebunii."},{"v":10,"t":"Natalie a fost convins de ei să se lase ales episcop al acestei erezii, cu un salariu, plătit de ei, de o sută cincizeci de dinari pe lună."},{"v":11,"t":"După ce s-a unit astfel cu ei, a fost avertizat adesea de Domnul prin vedenii. Căci Dumnezeul îndurător și Domnul nostru Isus Hristos nu voia ca un martor al propriilor Lui suferințe, izgonit din Biserică, să piară."},{"v":12,"t":"Dar pentru că a luat în seamă puțin vedeniile, fiind prins în capcană de întâietatea pe care o avea între ei și de acea rușinoasă lăcomie care pierde pe foarte mulți, a fost biciuit de sfinții îngeri și pedepsit aspru toată noaptea. Atunci, sculându-se dimineața, s-a îmbrăcat în sac și s-a acoperit cu cenușă și, cu mare grabă și lacrimi, a căzut înaintea lui Zefirin, episcopul, tăvălindu-se la picioarele nu numai ale clericilor, ci și ale mirenilor; și a mișcat prin lacrimile lui Biserica milostivă a Hristosului îndurător. Și deși a folosit multe rugăminți și a arătat urmele loviturilor primite, abia a fost primit înapoi în împărtășanie."},{"v":13,"t":"Vom adăuga de la același scriitor și alte extrase despre ei, care sună astfel: Au tratat dumnezeieștile Scripturi cu nesocotință și fără teamă. Au lepădat canonul credinței străvechi; și pe Hristos nu l-au cunoscut. Nu se străduiesc să afle ce declară dumnezeieștile Scripturi, ci se ostenesc după orice formă de silogism care poate fi născocită ca să sprijine nelegiuirea lor. Și dacă cineva le aduce înainte un loc din dumnezeiasca Scriptură, ei văd dacă din el se poate face un silogism de formă conjunctivă sau disjunctivă."},{"v":14,"t":"Și, ca unii care sunt din pământ și vorbesc din pământ și nu-l cunosc pe Cel care vine de sus, își părăsesc sfintele scrieri ale lui Dumnezeu ca să se dedice geometriei. Euclid este măsurat cu osteneală de unii dintre ei; Aristotel și Teofrast sunt admirați; iar Galen este poate chiar adorat de unii."},{"v":15,"t":"Dar că cei care se slujesc de meșteșugurile necredincioșilor pentru părerile lor eretice și falsifică simpla credință a dumnezeieștilor Scripturi prin viclenia celor fără Dumnezeu sunt departe de credință, ce nevoie este să mai spun? De aceea și-au pus mâinile cu îndrăzneală pe dumnezeieștile Scripturi, pretinzând că le-au îndreptat."},{"v":16,"t":"Că nu spun minciuni despre ei în această privință, poate afla oricine dorește. Căci dacă va aduna cineva exemplarele lor, fiecare în parte, și le va compara unele cu altele, va afla că diferă mult."},{"v":17,"t":"Cele ale lui Asclepiade, de pildă, nu se potrivesc cu ale lui Teodot. Și multe dintre ele se pot procura, pentru că ucenicii lor au scris cu sârguință îndreptările, cum le numesc ei, adică stricăciunile, fiecăruia dintre ei. Iarăși, cele ale lui Hermofil nu se potrivesc cu acestea, iar cele ale lui Apolonide nu sunt în acord nici cu ele însele. Căci puteți compara cele pregătite de ei mai de timpuriu cu cele pe care le-au stricat mai târziu și le veți afla foarte deosebite."},{"v":18,"t":"Dar cât de îndrăzneață este această faptă, nu este de crezut că ei înșiși nu știu. Căci ori nu cred că dumnezeieștile Scripturi au fost rostite de Duhul Sfânt și astfel sunt necredincioși, ori se socotesc mai înțelepți decât Duhul Sfânt și atunci ce altceva sunt decât îndrăciți? Căci nu pot tăgădui săvârșirea faptei, de vreme ce exemplarele au fost scrise de propriile lor mâini. Pentru că nu au primit asemenea Scripturi de la învățătorii lor și nici nu pot înfățișa vreun exemplar din care au fost copiate."},{"v":19,"t":"Dar unii dintre ei nu au socotit că merită osteneala să le strice, ci pur și simplu tăgăduiesc Legea și proorocii și astfel, prin învățătura lor fără de lege și nelegiuită, sub pretext de har, s-au scufundat în adâncurile cele mai de jos ale pierzării. Să fie de ajuns despre acestea."}];
